export function TimelinePane({ rows, nowSec, fadeSec, rangeStartSec, rangeEndSec, expandLevel = "stream", selectedTimeSec = null, onSelectTime, interfaceNames }: TimelinePaneProps) {
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const [interfaceExpanded, setInterfaceExpanded] = useState<Record<string, boolean>>({});
  const [protoExpanded, setProtoExpanded] = useState<Record<string, boolean>>({});
