async function readDashboardLayouts(): Promise<DashboardLayout[]> {
  if (!existsSync(config.dashboardLayoutsFile)) return [DEFAULT_DASHBOARD_LAYOUT];
  try {
    const parsed = JSON.parse(await readFile(config.dashboardLayoutsFile, "utf8")) as unknown;
    if (!Array.isArray(parsed)) return [DEFAULT_DASHBOARD_LAYOUT];
    const layouts = parsed.map(normalizeDashboardLayout).filter(Boolean) as DashboardLayout[];
    return layouts.length > 0 ? layouts : [DEFAULT_DASHBOARD_LAYOUT];
  } catch {
    return [DEFAULT_DASHBOARD_LAYOUT];
  }
