  addTimelineEvent(input: NormalizedTimelineInput) {
    this.tick(input.time);
    this.latestTimelineTime = Math.max(this.latestTimelineTime ?? input.time, input.time);
    const row = this.ensureTimelineRow(input);
    row.firstSeen = Math.min(row.firstSeen, input.time);
    row.lastSeen = Math.max(row.lastSeen, input.time);

    if (input.kind === "stream_detected" || input.kind === "stream_recovered" || input.kind === "flow_detected" || input.kind === "flow_recovered") {
      row.active = true;
      const current = row.segments[row.segments.length - 1];
      if (!current || current.end !== null) {
        row.segments.push({ start: input.time, end: null });
      }
    } else if (input.kind === "stream_lost" || input.kind === "flow_lost") {
      row.active = false;
      const current = row.segments[row.segments.length - 1];
      if (current && current.end === null) {
        current.end = input.time;
      } else if (!current) {
        row.segments.push({ start: input.time, end: input.time });
      }
    }

    this.pruneTimeline(this.latestTimelineTime);
    this.enforceTimelineBudget();
    this.emit("timeline:update");
  }

  addMetric(input: NormalizedMetricInput) {
    this.tick(input.time);
    // Lifecycle projection owns identity and active/lost state. A historical raw
    // metric must not recreate a stream or flow that has already been lost.
    const stream = this.streams.get(input.streamKey);
    if (!stream) return;
    const flow = stream.flows.find((item) => item.flowKey === input.flowKey);
    if (!flow) return;
    if (input.interfaceId !== undefined) {
      stream.interfaceId ??= input.interfaceId;
      flow.interfaceId ??= input.interfaceId;
      const interfaceName = this.interfaceById(input.interfaceId)?.name;
      if (nowWall - lostSince < this.lostRetentionSec) continue;
      this.lostSinceWall.delete(streamKey);
      const stream = this.streams.get(streamKey);
      if (stream) {
        for (const flow of stream.flows) {
          this.flowLostSinceWall.delete(flow.flowKey);
          this.flowHistory.delete(flow.flowKey);
          this.flowSparklines.delete(flow.flowKey);
        }
      }
      this.streams.delete(streamKey);
      changed = true;
    }
    this.pruneStreamSortOrder();
    return changed;
  }

  private pruneTimeline(now: number) {
    const cutoff = now - this.timelineWindowSec;
    for (const [key, row] of this.timeline) {
      const retained = row.segments
        .map((segment) => {
          const effectiveEnd = segment.end ?? now;
          if (effectiveEnd <= cutoff) return undefined;
          return {
            start: Math.max(segment.start, cutoff),
            end: segment.end
          };
        })
        .filter((segment): segment is NonNullable<typeof segment> => segment !== undefined);

      if (retained.length === 0 && row.lastSeen <= cutoff && !row.active) {
        this.timeline.delete(key);
        continue;
      }

      row.segments = retained;
      if (retained.length > 0) {
        row.firstSeen = retained[0].start;
      }
    }
  }

  private enforceTimelineBudget() {
    if (this.timeline.size <= this.maxTimelineRows) return;

    const removable = [...this.timeline.entries()]
      .filter(([, row]) => !row.active)
      .sort((a, b) => a[1].lastSeen - b[1].lastSeen);

    for (const [key] of removable) {
      if (this.timeline.size <= this.maxTimelineRows) break;
      this.timeline.delete(key);
    }

    if (this.timeline.size <= this.maxTimelineRows) return;

    const forced = [...this.timeline.entries()]
      .sort((a, b) => {
        if (a[1].rowType !== b[1].rowType) {
          return a[1].rowType === "flow" ? -1 : 1;
        }
        return a[1].lastSeen - b[1].lastSeen;
      });

    for (const [key] of forced) {
      if (this.timeline.size <= this.maxTimelineRows) break;
      this.timeline.delete(key);
    }
  }

  private pruneStreamSortOrder() {
    for (const streamKey of this.streamSortOrder.keys()) {
      if (!this.streams.has(streamKey)) this.streamSortOrder.delete(streamKey);
    }
  }

  private overviewForStream(stream: StreamState): OverviewStats {
    const stats = stream.flows.map((flow) => this.overviewForFlow(flow, stream.streamKey));
    return {
      gap: sumOverview(stats, "gap"),
      gap: sumOverview(stats, "gap"),
      dup: sumOverview(stats, "dup"),
      reorder: sumOverview(stats, "reorder"),
      events: this.eventCountsByStream.get(stream.streamKey) ?? 0
    };
  }

  private overviewForFlow(flow: FlowState, streamKey: string): OverviewStats {
    return {
      gap: statValue(flow.metrics["seq_stats.gap"]),
      dup: statValue(flow.metrics["seq_stats.dup"]),
      reorder: statValue(flow.metrics["seq_stats.reorder"]),
      events: (this.eventCountsByFlow.get(flow.flowKey) ?? 0) + (this.eventCountsByStreamOnly.get(streamKey) ?? 0)
    };
  }

  private incrementEventCounts(event: EventLogItem, delta: 1 | -1) {
    if (event.streamKey) updateCount(this.eventCountsByStream, event.streamKey, delta);
    if (event.streamKey && !event.flowKey) updateCount(this.eventCountsByStreamOnly, event.streamKey, delta);
    if (event.flowKey) updateCount(this.eventCountsByFlow, event.flowKey, delta);
  }

  private attachInterfaceName(stream: StreamState) {
    if (stream.interfaceId !== undefined) stream.interfaceName = this.interfaceById(stream.interfaceId)?.name ?? stream.interfaceName;
    for (const flow of stream.flows) {
      flow.interfaceId ??= stream.interfaceId;
      if (flow.interfaceId !== undefined) flow.interfaceName = this.interfaceById(flow.interfaceId)?.name ?? flow.interfaceName ?? stream.interfaceName;
    }
  }

  private interfaceById(interfaceId: number) {
    return this.interfaces.get(`if:${interfaceId}`);
  }

  private refreshInterfaceNames() {
    for (const stream of this.streams.values()) this.attachInterfaceName(stream);
  }

  private refreshTimelineNames() {
    for (const row of this.timeline.values()) {
      if (row.interfaceId !== undefined) {
        row.interfaceName = this.interfaceById(row.interfaceId)?.name ?? row.interfaceName;
      }
    }
  }

  private ensureTimelineRow(input: NormalizedTimelineInput): TimelineRow {
    const timelineKey = input.subjectType === "flow" ? `${input.streamKey}::${input.flowKey ?? ""}` : input.streamKey;
    const existing = this.timeline.get(timelineKey);
    if (existing) {
      existing.interfaceId = input.interfaceId ?? existing.interfaceId;
      if (existing.interfaceId !== undefined) {
        existing.interfaceName = this.interfaceById(existing.interfaceId)?.name ?? existing.interfaceName;
      }
      existing.kind = input.proto;
      existing.proto = input.proto;
      existing.label = input.label || existing.label;
      existing.role = input.role ?? existing.role;
      existing.endpointSrc = input.endpointSrc ?? existing.endpointSrc;
      existing.endpointDst = input.endpointDst ?? existing.endpointDst;
      existing.scope = input.scope.known ? input.scope : existing.scope;
      return existing;
    }

    const interfaceName = input.interfaceId !== undefined ? this.interfaceById(input.interfaceId)?.name : undefined;
    const row: TimelineRow = {
      rowType: input.subjectType === "flow" ? "flow" : "stream",
      streamKey: input.streamKey,
      flowKey: input.flowKey,
      parentStreamKey: input.subjectType === "flow" ? input.streamKey : undefined,
      kind: input.proto,
      proto: input.proto,
      label: input.label,
      role: input.role,
      endpointSrc: input.endpointSrc,
      endpointDst: input.endpointDst,
      interfaceId: input.interfaceId,
      interfaceName,
      scope: input.scope,
      active: input.kind !== "stream_lost",
      firstSeen: input.time,
      lastSeen: input.time,
      segments: []
    };
    this.timeline.set(timelineKey, row);
    return row;
  }
}

function mergeFlows(existing: FlowState[], incoming: FlowState[], lostSinceWall: Map<string, number>, observedAtWall?: number) {
  const byKey = new Map(existing.map((flow) => [flow.flowKey, flow]));
  const seen = new Set<string>();
  const merged = incoming.map((flow) => {
    seen.add(flow.flowKey);
    lostSinceWall.delete(flow.flowKey);
    return {
      ...byKey.get(flow.flowKey),
      ...flow,
      metrics: byKey.get(flow.flowKey)?.metrics ?? flow.metrics
    };
  });

  if (observedAtWall !== undefined) {
    for (const flow of existing) {
      if (seen.has(flow.flowKey)) continue;
      if (!lostSinceWall.has(flow.flowKey)) {
        lostSinceWall.set(flow.flowKey, observedAtWall);
      }
      merged.push({
        ...flow,
        active: false
      });
    }
  }

  return merged;
