function TimelineInterfaceLane({
  group,
  range,
  cursorPercent,
  cursorSec,
  expanded,
  isHovered,
  onHoverChange,
  onToggle
}: {
  group: {
    key: string;
    label: string;
    rows: Array<{ stream: TimelineRow; flows: TimelineRow[] }>;
    segments: Array<{ start: number; end: number }>;
    firstSeen: number;
    lastSeen: number;
    active: boolean;
  };
  range: { start: number; end: number };
  cursorPercent: number;
  cursorSec: number;
  expanded: boolean;
  isHovered: boolean;
  onHoverChange: (key: string | null) => void;
  onToggle: () => void;
}) {
  const focused = group.segments.some((segment) => cursorSec >= segment.start && cursorSec <= segment.end);
  const focusClass = focused ? " timeline-row-cursor-focused" : isHovered ? " timeline-row-hovered" : "";
  return (
    <div
      className={`timeline-interface-header${focusClass}`}
      onPointerEnter={() => onHoverChange(group.key)}
      onPointerLeave={() => onHoverChange(null)}
    >
      <div className="timeline-interface-label" title={group.key}>
        <strong>
          <button type="button" className="timeline-toggle" onClick={(event) => { event.stopPropagation(); onToggle(); }} aria-label={expanded ? "Collapse interface rows" : "Expand interface rows"}>
            <Icon name="expand" size={15} className={expanded ? "is-expanded" : ""} />
          </button>
          <span className="timeline-label-text">{group.label}</span>
          <em>{group.rows.length}</em>
        </strong>
      </div>
      <div className="timeline-row-track timeline-interface-track">
        <div className="timeline-cursor-line" style={{ left: `${cursorPercent}%` }} aria-hidden="true" />
        {group.segments.map((segment, index) => {
          const start = percent(segment.start, range.start, range.end);
          const end = percent(segment.end, range.start, range.end);
          return (
            <div
              key={`${group.key}:${index}:${segment.start}`}
