std::tm utc_tm(double now) {
	std::time_t tt = static_cast<std::time_t>(std::floor(now));
	std::tm tm{};
	gmtime_r(&tt, &tm);
	return tm;
}
}

timeline_sink::timeline_sink(config cfg)
	: m_writer(cfg.live_writer)
	, m_capture_id(std::move(cfg.capture_id))
	, m_history_root(std::move(cfg.history_root))
	, m_checkpoint_root(cfg.checkpoint_root.empty()
		? m_history_root / "checkpoint" : std::move(cfg.checkpoint_root)) {
	if(!m_history_root.empty()) {
		std::filesystem::create_directories(m_history_root);
		std::filesystem::create_directories(m_checkpoint_root);
	}
}

int timeline_sink::emit(const timeline_record &e) {
	update_active_rows(e);

	json j{
		{"capture_id", m_capture_id},
		{"seq", m_seq++},
		{"time", e.time_epoch},
		{"kind", e.kind},
		{"source", "pcap"},
		{"subject", e.subject},
	};

	if(e.detail.is_null() == false && e.detail.empty() == false) {
		j["detail"] = e.detail;
	}

	ensure_history_open(e.time_epoch);
	write_history_line(j);
	emit_checkpoint_if_needed(e.time_epoch);
	return m_writer.dump(j);
}

int timeline_sink::emit(double time_epoch, std::string kind, json subject, json detail) {
	return emit(timeline_record{
		.time_epoch = time_epoch,
		.kind = std::move(kind),
		.subject = std::move(subject),
		.detail = std::move(detail),
	});
}

timeline_sink::hourly_slot timeline_sink::slot_for(double now) {
	auto tm = utc_tm(now);
	return hourly_slot{
		.year = tm.tm_year + 1900,
		.month = tm.tm_mon + 1,
		.day = tm.tm_mday,
		.hour = tm.tm_hour,
	};
}

timeline_sink::minute_slot timeline_sink::minute_slot_for(double now) {
	auto tm = utc_tm(now);
	return minute_slot{
		.year = tm.tm_year + 1900,
		.month = tm.tm_mon + 1,
		.day = tm.tm_mday,
		.hour = tm.tm_hour,
		.minute = tm.tm_min,
	};
}

std::filesystem::path timeline_sink::build_history_path(const std::filesystem::path &root, const hourly_slot &slot) {
	char day[16];
	char hour[16];
	std::snprintf(day, sizeof(day), "%04d%02d%02d", slot.year, slot.month, slot.day);
	std::snprintf(hour, sizeof(hour), "%02d.ndjson", slot.hour);
	return root / day / hour;
}

std::filesystem::path timeline_sink::build_checkpoint_path(const std::filesystem::path &root, const minute_slot &slot) {
	char day[16];
	char minute_file[32];
	std::snprintf(day, sizeof(day), "%04d%02d%02d", slot.year, slot.month, slot.day);
	std::snprintf(minute_file, sizeof(minute_file), "%02d%02d.json", slot.hour, slot.minute);
	return root / day / minute_file;
}

void timeline_sink::ensure_history_open(double now) {
	if(m_history_root.empty()) {
		return;
	}

	const auto slot = slot_for(now);
	if(m_history_file.stream.is_open() && m_history_file.slot == slot) {
		return;
	}

	if(m_history_file.stream.is_open()) {
		m_history_file.stream.flush();
		m_history_file.stream.close();
	}

	m_history_file.slot = slot;
	m_history_file.path = build_history_path(m_history_root, slot);
	std::filesystem::create_directories(m_history_file.path.parent_path());
	m_history_file.stream.open(m_history_file.path, std::ios::app);
}

void timeline_sink::write_history_line(const json &line) {
	if(!m_history_file.stream.is_open()) {
		return;
	}

	m_history_file.stream << line.dump() << '\n';
	m_history_file.stream.flush();
}

void timeline_sink::update_active_rows(const timeline_record &e) {
	const auto kind = e.kind;
	const bool is_detect =
		kind == "stream_detected" || kind == "stream_recovered" ||
		kind == "flow_detected" || kind == "flow_recovered";
	const bool is_lost = kind == "stream_lost" || kind == "flow_lost";
	if(!is_detect && !is_lost) {
		return;
	}

	if(!e.subject.is_object()) {
		return;
	}

	const std::string subject_type = e.subject.value("type", "");
	const std::string stream_key = e.subject.value("stream_key", "");
	if(stream_key.empty()) {
		return;
	}

	std::string key = stream_key;
	if(subject_type == "flow") {
		const std::string flow_key = e.subject.value("flow_key", "");
		if(flow_key.empty()) {
			return;
		}
		key += "::" + flow_key;
	}

#include "stm_projector.h"

#include <chrono>
#include <algorithm>
#include <fstream>
#include <thread>
#include <utility>
#include <vector>

#include "trace.h"

namespace {
std::string projector_capture_id() {
	return "stm-projector";
}

bool as_event_record(const json &input, event_record &out) {
	if(!input.is_object() || input.value("record_type", std::string{}) != "event") {
		return false;
	}
	const double time = input.value("event_time", input.value("time", 0.0));
	const std::string type = input.value("type", std::string{});
	if(time <= 0.0 || type.empty()) {
		return false;
	}
	out = event_record{
		.time_epoch = time,
		.type = type,
		.source = input.value("source", json::object()),
		.detail = input.value("detail", json::object()),
	};
	return true;
}

enum class journal_kind {
	event,
	metrics,
};

struct pending_journal_record {
	double time{0.0};
	journal_kind kind{journal_kind::event};
	std::size_t ordinal{0};
	json record;
};

double record_time(const json &record, journal_kind kind) {
	if(kind == journal_kind::event) {
		return record.value("event_time", record.value("time", 0.0));
	}
	return record.value("time", 0.0);
}
}

stm_projector::stm_projector(config cfg)
	: m_cfg(std::move(cfg))
	, m_events(m_cfg.event_journal_dir)
	, m_metrics(m_cfg.metrics_journal_dir) {
	if(m_cfg.state_file.empty()) {
		m_cfg.state_file = m_cfg.output_dir / "projector-state.json";
	}
	std::filesystem::create_directories(m_cfg.output_dir);
	m_timeline_writer = std::make_unique<writer>("STM_PROJECTOR_TIMELINE",
	                                            (m_cfg.output_dir / "timeline" / "live.ndjson").string(),
	                                            m_cfg.timeline_rotate_size_bytes,
	                                            m_cfg.timeline_rotate_files,
	                                            false);
	m_timeline_sink = std::make_unique<timeline_sink>(timeline_sink::config{
		.live_writer = *m_timeline_writer,
		.capture_id = projector_capture_id(),
		.history_root = m_cfg.output_dir / "timeline" / "events",
		.checkpoint_root = m_cfg.output_dir / "timeline" / "checkpoint",
	});
	m_timeline_projector = std::make_unique<timeline_projector>(*m_timeline_sink);
	m_metrics_history = std::make_unique<metrics_history_sink>(metrics_history_sink::config{
		.root_dir = m_cfg.output_dir / "metrics",
		.raw_dir = "raw",
		.rollup_1m_dir = "rollup/1m",
	});
	m_stream_state = std::make_unique<stream_state_projector>(stream_state_projector::config{
		.root_dir = m_cfg.output_dir / "streams",
		.part_size_bytes = m_cfg.part_size_bytes,
		.retention_hours = m_cfg.retention_hours,
	});
	m_topology_projector = std::make_unique<topology_projector>();
	m_topology_state = std::make_unique<topology_state_projector>(topology_state_projector::config{
		.root_dir = m_cfg.output_dir / "topology",
		.checkpoint_interval_sec = m_cfg.topology_checkpoint_interval_sec,
		.part_size_bytes = m_cfg.part_size_bytes,
		.retention_hours = m_cfg.retention_hours,
	});
	m_topology_writer = std::make_unique<writer>("STM_PROJECTOR_TOPOLOGY",
	                                            (m_cfg.output_dir / "topology" / "live.ndjson").string(),
	                                            m_cfg.timeline_rotate_size_bytes,
	                                            m_cfg.timeline_rotate_files,
	                                            false);
	m_topology_events_writer = std::make_unique<time_rotating_writer>("STM_PROJECTOR_TOPOLOGY_EVENTS",
	                                                                  m_cfg.output_dir / "topology" / "events",
	                                                                  m_cfg.part_size_bytes,
	                                                                  m_cfg.retention_hours);
	m_metrics_v2_writer = std::make_unique<time_rotating_writer>("STM_PROJECTOR_METRICS_V2",
	                                                            m_cfg.output_dir / "metrics" / "samples",
	                                                            m_cfg.part_size_bytes,
	                                                            m_cfg.retention_hours);
	load_state();
}

int stm_projector::run_once() {
	std::vector<pending_journal_record> pending;
	std::size_t ordinal = 0;
	const auto event_result = m_events.read_after(m_event_cursor, [&](const json &record) {
		pending.push_back(pending_journal_record{
			.time = record_time(record, journal_kind::event),
			.kind = journal_kind::event,
			.ordinal = ordinal++,
			.record = record,
		});
		return 0;
	});
	const auto metrics_result = m_metrics.read_after(m_metrics_cursor, [&](const json &record) {
		pending.push_back(pending_journal_record{
			.time = record_time(record, journal_kind::metrics),
			.kind = journal_kind::metrics,
			.ordinal = ordinal++,
			.record = record,
		});
		return 0;
	});
	std::stable_sort(pending.begin(), pending.end(), [](const auto &left, const auto &right) {
		if(left.time != right.time) return left.time < right.time;
		if(left.kind != right.kind) return left.kind == journal_kind::event;
		return left.ordinal < right.ordinal;
	});
	for(const auto &item : pending) {
		const int rc = item.kind == journal_kind::event ? project_event(item.record) : project_metrics(item.record);
		if(rc != 0) return rc;
	}
	if(event_result.advanced || metrics_result.advanced) {
		save_state();
	}
	trace(1, "projector: events=%zu metrics=%zu", event_result.records, metrics_result.records);
	return 0;
}

int stm_projector::run_follow() {
	for(;;) {
		if(run_once() != 0) {
			return -1;
		}
		std::this_thread::sleep_for(m_cfg.poll_interval);
	}
}

void stm_projector::load_state() {
	std::ifstream input(m_cfg.state_file);
	if(!input) {
		return;
	}
	try {
		json state;
		input >> state;
		m_event_cursor = journal_reader::cursor_from_json(state.value("event_cursor", json::object()));
		m_metrics_cursor = journal_reader::cursor_from_json(state.value("metrics_cursor", json::object()));
		if(m_stream_state) m_stream_state->import_state(state.value("stream_state", json::object()));
		if(state.contains("current_metrics") && state["current_metrics"].is_array()) m_current_metrics = state["current_metrics"].get<json::array_t>();
		if(state.contains("current_interfaces") && state["current_interfaces"].is_array()) m_current_interfaces = state["current_interfaces"].get<json::array_t>();
		if(state.contains("active_alerts") && state["active_alerts"].is_object()) m_active_alerts = state["active_alerts"];
		if(state.contains("last_event_record_id") && state["last_event_record_id"].is_string()) m_last_event_record_id = state["last_event_record_id"];
		if(state.contains("last_metrics_record_id") && state["last_metrics_record_id"].is_string()) m_last_metrics_record_id = state["last_metrics_record_id"];
		if(m_topology_state) m_topology_state->import_state(state.value("topology_state", json::object()));
	}
	catch(const std::exception &e) {
		trace(1, "projector: state load failed: %s", e.what());
	}
}

void stm_projector::save_state() const {
	if(!m_cfg.state_file.parent_path().empty()) {
		std::filesystem::create_directories(m_cfg.state_file.parent_path());
	}
	const auto temporary = m_cfg.state_file.string() + ".tmp";
	std::ofstream output(temporary, std::ios::trunc);
	if(!output) {
		trace(1, "projector: state write failed: %s", temporary.c_str());
		return;
	}
	output << json{
		{"schema_version", 1},
		{"event_cursor", journal_reader::cursor_json(m_event_cursor)},
		{"metrics_cursor", journal_reader::cursor_json(m_metrics_cursor)},

