		writer &live_writer;
		std::string capture_id;
		std::filesystem::path history_root;
		std::filesystem::path checkpoint_root;
	};

	explicit timeline_sink(config cfg);
	virtual ~timeline_sink() = default;

	int emit(const timeline_record &e);
	int emit(double time_epoch, std::string kind, json subject, json detail = json::object());

private:
	struct hourly_slot {
		int year{0};
		int month{0};
		int day{0};
		int hour{0};

		bool operator==(const hourly_slot &rhs) const = default;
	};

	struct history_file {
		hourly_slot slot{};
		std::filesystem::path path;
		std::ofstream stream;
	};

	struct minute_slot {
		int year{0};
		int month{0};
		int day{0};
		int hour{0};
		int minute{0};

		bool operator==(const minute_slot &rhs) const = default;
	};

	struct timeline_row_state {
		json row{json::object()};
		double first_seen{0.0};
		double last_seen{0.0};
	};

	writer &m_writer;
	std::string m_capture_id;
	std::filesystem::path m_history_root;
	std::filesystem::path m_checkpoint_root;
	std::uint64_t m_seq{0};
	history_file m_history_file;
	std::unordered_map<std::string, timeline_row_state> m_active_rows;
	minute_slot m_last_checkpoint_slot{};
	bool m_has_checkpoint_slot{false};

	static hourly_slot slot_for(double now);
	static minute_slot minute_slot_for(double now);
	static std::filesystem::path build_history_path(const std::filesystem::path &root, const hourly_slot &slot);
	static std::filesystem::path build_checkpoint_path(const std::filesystem::path &root, const minute_slot &slot);
	void ensure_history_open(double now);
	void write_history_line(const json &line);
	void update_active_rows(const timeline_record &e);
	void emit_checkpoint_if_needed(double now);
	void write_checkpoint(const minute_slot &slot, double now);
};

