void timeline_sink::update_active_rows(const timeline_record &e) {
	const auto kind = e.kind;
	const bool is_detect =
		kind == "stream_detected" || kind == "stream_recovered" ||
		kind == "flow_detected" || kind == "flow_recovered";
	const bool is_lost = kind == "stream_lost" || kind == "flow_lost";
	if(!is_detect && !is_lost) {
		return;
	}

	if(!e.subject.is_object()) {
		return;
	}

	const std::string subject_type = e.subject.value("type", "");
	const std::string stream_key = e.subject.value("stream_key", "");
	if(stream_key.empty()) {
		return;
	}

	std::string key = stream_key;
	if(subject_type == "flow") {
		const std::string flow_key = e.subject.value("flow_key", "");
		if(flow_key.empty()) {
			return;
		}
		key += "::" + flow_key;
	}

	if(is_lost) {
		m_active_rows.erase(key);
		return;
	}

	auto it = m_active_rows.find(key);
	if(it == m_active_rows.end()) {
		timeline_row_state created{};
		created.first_seen = e.time_epoch;
		created.last_seen = e.time_epoch;
		created.row = json{
			{"key", key},
			{"type", subject_type},
			{"stream_key", stream_key},
			{"flow_key", e.subject.value("flow_key", "")},
			{"parent_stream_key", subject_type == "flow" ? stream_key : ""},
			{"proto", e.subject.value("proto", "")},
			{"interface_id", e.subject.contains("interface_id") ? e.subject["interface_id"] : json(nullptr)},
			{"label", e.subject.value("label", "")},
			{"role", e.subject.value("role", "")},
			{"subject", e.subject},
		};
		m_active_rows.emplace(key, std::move(created));
		return;
	}

	it->second.last_seen = e.time_epoch;
	auto &row = it->second.row;
	row["proto"] = e.subject.value("proto", row.value("proto", ""));
	if(e.subject.contains("interface_id")) {
		row["interface_id"] = e.subject["interface_id"];
	}
	if(e.subject.contains("label")) {
		row["label"] = e.subject["label"];
	}
	if(e.subject.contains("role")) {
		row["role"] = e.subject["role"];
	}
	row["subject"] = e.subject;
}

void timeline_sink::emit_checkpoint_if_needed(double now) {
	if(m_checkpoint_root.empty()) {
		return;
	}

	const auto slot = minute_slot_for(now);
	if(!m_has_checkpoint_slot) {
		m_last_checkpoint_slot = slot;
		m_has_checkpoint_slot = true;
		return;
	}

	if(slot == m_last_checkpoint_slot) {
		return;
	}

	write_checkpoint(m_last_checkpoint_slot, now);
	m_last_checkpoint_slot = slot;
}

void timeline_sink::write_checkpoint(const minute_slot &slot, double now) {
	json rows = json::array();
	std::vector<const timeline_row_state*> ordered;
	ordered.reserve(m_active_rows.size());
	for(const auto &kv : m_active_rows) {
		ordered.push_back(&kv.second);
	}
	std::sort(ordered.begin(), ordered.end(), [](const timeline_row_state *a, const timeline_row_state *b) {
		return a->row.value("key", "") < b->row.value("key", "");
	});

	for(const auto *state : ordered) {
		json item = state->row;
		item["first_seen"] = state->first_seen;
		item["last_seen"] = state->last_seen;
		rows.push_back(std::move(item));
	}

	json doc{
		{"capture_id", m_capture_id},
		{"time", now},
		{"slot", json{
			{"year", slot.year},
			{"month", slot.month},
			{"day", slot.day},
			{"hour", slot.hour},
			{"minute", slot.minute},
		}},
		{"active_rows", std::move(rows)},
	};

	const auto path = build_checkpoint_path(m_checkpoint_root, slot);
	std::filesystem::create_directories(path.parent_path());
	std::ofstream ofs(path, std::ios::trunc);
	if(!ofs.is_open()) {
		return;
	}
	ofs << doc.dump() << '\n';
	ofs.flush();
