function streamEndpointLabel(stream: StreamListItem) {
  const primaryFlow = stream.flows.find((flow) => flow.role === "media") ?? stream.flows[0];
  return stream.sessionDst
    ?? stream.endpointB
    ?? primaryFlow?.endpointDst
    ?? stream.endpointA
    ?? primaryFlow?.endpointSrc
    ?? endpointFromStreamKey(stream.streamKey)
    ?? "Endpoint unknown";
}

function endpointFromStreamKey(streamKey: string) {
  const fields = new Map(streamKey.split("|").map((part) => {
    const separator = part.indexOf("=");
    return separator < 0 ? ["", ""] : [part.slice(0, separator), part.slice(separator + 1)];
  }));
  for (const key of ["session_dst", "ep", "b", "dst", "a", "src"]) {
    const value = fields.get(key);
    if (value) return value;
  }
  return undefined;
}

function LastSeen({ epochSec }: { epochSec?: number }) {
  const absoluteDateTime = formatAbsoluteDateTime(epochSec);
  return <time className="stream-last-seen" dateTime={epochSec ? new Date(epochSec * 1000).toISOString() : undefined} title={absoluteDateTime}>{formatRelativeTime(epochSec)}</time>;
}

function DescendantCountBadge({ count }: { count: number }) {
  return <span className="tree-count-badge">{count}</span>;
}

function displayFlowRole(role: string) {
  if (["default", "flow", "unknown"].includes(role)) return undefined;
  return role.replace("_", " ");
}

function streamBitrateOf(stream: StreamListItem) {
  return stream.bitrate.value ?? stream.bitrate.avg ?? 0;
}

