}

function TimelineLane({
  rowKey,
  row,
  range,
  cursorPercent,
  cursorSec,
  fadeSec,
  isHovered,
  onHoverChange,
  childCount = 0,
  expanded = true,
  onToggle
}: {
  rowKey: string;
  row: TimelineRow;
  range: { start: number; end: number };
  cursorPercent: number;
  cursorSec: number;
  fadeSec: number;
  isHovered: boolean;
  onHoverChange: (key: string | null) => void;
  childCount?: number;
  expanded?: boolean;
  onToggle?: () => void;
}) {
  const focused = row.segments.some((segment) => {
    const end = segment.end ?? range.end;
    return cursorSec >= segment.start && cursorSec <= end;
  });
  const focusClass = focused ? " timeline-row-cursor-focused" : isHovered ? " timeline-row-hovered" : "";

  return (
    <div
      className={`timeline-row ${row.rowType === "flow" ? "timeline-row-flow" : "timeline-row-stream"}${focusClass}`}
      onPointerEnter={() => onHoverChange(rowKey)}
