    >
      <div className="timeline-row-label" title={row.flowKey ?? row.streamKey}>
        <strong>
          {onToggle ? (
            <button type="button" className="timeline-toggle" onClick={(event) => { event.stopPropagation(); onToggle(); }} aria-label={expanded ? "Collapse flow rows" : "Expand flow rows"}>
