        </strong>
      </div>
      <div className="timeline-row-track">
        <div className="timeline-cursor-line" style={{ left: `${cursorPercent}%` }} aria-hidden="true" />
        {row.segments.map((segment, index) => renderSegment(row, segment, index, range, fadeSec))}
      </div>
    </div>
  );
}

