.timeline-chart {
  --timeline-label-width: clamp(196px, 24vw, 320px);
  gap: 0;
  background:
    linear-gradient(90deg, var(--chart-grid) 1px, transparent 1px) var(--timeline-label-width) 0 / 96px 100%,
    linear-gradient(var(--chart-grid) 1px, transparent 1px) 0 0 / 100% 32px,
    var(--surface);
}

.timeline-axis,
.timeline-interface-header,
.timeline-proto-row,
.timeline-row {
  grid-template-columns: var(--timeline-label-width) minmax(0, 1fr);
  gap: var(--space-2);
}

.timeline-interface-header,
.timeline-proto-row {
  min-height: 32px;
  background: transparent;
}

.timeline-row {
  min-height: 42px;
  height: 100%;
}

.timeline-interface-label,
.timeline-proto-label,
.timeline-row-label,
.timeline-axis-label {
  min-width: 0;
  align-self: stretch;
  padding: 0 var(--space-2);
  border-right: 1px solid color-mix(in srgb, var(--line) 74%, transparent);
  background: color-mix(in srgb, var(--surface-muted) 88%, var(--surface));
}

.timeline-interface-label,
.timeline-proto-label,
.timeline-row-label {
  display: grid;
  align-content: center;
}

.timeline-proto-label {
  padding-left: calc(var(--space-2) + 14px);
}
.timeline-row.timeline-row-cursor-focused .timeline-row-label {
  background: var(--surface-muted);
}

/* The axis is already sticky; the context sits on top of it only while scrolling. */
.timeline-sticky-context {
  position: absolute;
  inset: 0 0 auto;
  z-index: 5;
  display: flex;
  align-items: center;
  height: 28px;
  padding: 0 var(--space-2);
  overflow: hidden;
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--surface-raised) 94%, var(--surface));
  color: var(--text-strong);
  font-size: var(--font-size-xs);
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
}

