export async function registerRoutes(
  app: FastifyInstance,
  store: StreamStore,
  maintenanceSettings: MaintenanceSettings,
  alertsSettings: AlertsSettings | undefined,
  protocolMapSettings: ProtocolMapSettings | undefined,
  applyRuntimeSettings: (values: RuntimeSettings) => void
) {
  app.addHook("onSend", async (_request, reply, payload) => {
    reply.header("Cache-Control", "no-store");
    return payload;
  });

  app.get("/api/config", async () => ({
    lostRetentionSec: config.lostRetentionSec,
    historyWindowSec: config.historyWindowSec,
    staleAfterSec: config.staleAfterSec,
    diagnosticLog: config.diagnosticLog
  }));

  app.get("/api/maintenance/frontend-settings", async () => maintenanceSettings.get());

  app.put<{ Body: { revision?: unknown; values?: unknown } }>("/api/maintenance/frontend-settings", async (request, reply) => {
    try {
      const updated = await maintenanceSettings.update(request.body?.revision, request.body?.values);
      applyRuntimeSettings(updated.values);
      return updated;
    } catch (error) {
      if (error instanceof SettingsConflictError) return reply.code(409).send({ error: error.message });
      if (error instanceof SettingsValidationError) return reply.code(400).send({ error: error.message });
      request.log.error({ error }, "failed to persist maintenance settings");
      return reply.code(500).send({ error: "failed to persist settings" });
    }
  });

  app.get("/api/maintenance/alerts", async (_request, reply) => {
    if (!alertsSettings) return reply.code(503).send({ error: "STM config file is not configured for this server" });
    try { return await alertsSettings.get(); }
    catch (error) { return reply.code(400).send({ error: error instanceof Error ? error.message : "failed to read alerts config" }); }
  });

  app.put<{ Body: { revision?: unknown; document?: unknown } }>("/api/maintenance/alerts", async (request, reply) => {
    if (!alertsSettings) return reply.code(503).send({ error: "STM config file is not configured for this server" });
    try { return await alertsSettings.update({ revision: request.body?.revision, document: request.body?.document }); }
    catch (error) {
