monitor::monitor()
	: monitor(config{}) {
}

monitor::monitor(config cfg)
	: m_cfg(std::move(cfg)),
	  m_reorder(m_cfg.reorder_holdback_sec) {
	m_init_status = init();
}

monitor::~monitor() {
}

int monitor::init() {
	{
		std::ios::sync_with_stdio(false);
		std::cin.tie(nullptr);
	}

	if(m_cfg.protocol_map_file.empty() == false) {
		if(m_protocol_map.load(m_cfg.protocol_map_file) != 0) {
			return -1;
		}
	}


	m_logs = std::make_unique<log_pipeline>(m_cfg.log);
	m_alerts = std::make_unique<alert_evaluator>(m_logs->events());
	if(!m_cfg.alert_config_file.empty() && m_alerts->load(m_cfg.alert_config_file) != 0) {
		return -1;
	}

	m_streams = std::make_unique<stream_registry>(m_protocol_map, m_logs->events());
	m_interfaces = std::make_unique<netif::interfaces>(netif::config{}, m_logs->events());

	m_pcap_source = pcap_input::make_source(m_cfg.input);
	if(!m_pcap_source) {
		trace(0, "error: failed to create pcap input source");
		return -1;
	}
	m_pcap_source->set_callback([this](const std::filesystem::path &path) {
		return process_pcap(path);
	});

	return 0;
}

int monitor::run() {
	if(m_init_status != 0) {
		return 1;
	}
	if(!m_pcap_source) {
		trace(0, "error: pcap input source is not initialized");
		return 1;
	}
	return m_pcap_source->run();
}

bool monitor::process_pcap(const std::filesystem::path& file_path) {
	std::string command = tshark::build_read_command(file_path, m_cfg.tshark, m_protocol_map.decode_as_rules());

	FILE* pipe = popen(command.c_str(), "r");
	if(!pipe) {
		return false;
	}

	const bool parse_ok = (process_tsv(pipe) == 0);
	if(!parse_ok) {
		trace(0, "warn: parse_tsv failed for %s", file_path.filename().string().c_str());
	}

	int status = pclose(pipe);
	if(status == -1) {
		trace(0, "warn: pclose failed for %s", file_path.filename().string().c_str());
		return false;
	}

	if(WIFEXITED(status)) {
		int exit_code = WEXITSTATUS(status);
		if(exit_code == 0) {
			return parse_ok;
		}

		trace(0, "warn: tshark failed for %s, exit_code=%d",
		      file_path.filename().string().c_str(),
		      exit_code);
		return false;
	}

	if(WIFSIGNALED(status)) {
		trace(0, "warn: tshark terminated by signal for %s, signal=%d",
		      file_path.filename().string().c_str(),
		      WTERMSIG(status));
		return false;
	}

	trace(0, "warn: tshark ended unexpectedly for %s, status=%d",
	      file_path.filename().string().c_str(),
	      status);

	return false;
}

int monitor::process_tsv(FILE *pipe) {
	tsv::ctx tc;
	char line[32768];

	m_reorder.reset();

	if(fgets(line, sizeof(line), pipe) == nullptr) {
		trace(1, "info: tshark output is empty");
		return 0;
	}
	if(!tsv::init_ctx(tc, line)) {
		return -1;
	}

	trace(7, "%s", line);

	while(fgets(line, sizeof(line), pipe) != nullptr) {
		trace(7, "%s", line);

		std::string buffered_line{line};
		tsv::row_t row;
		tsv::split(buffered_line, row);

		double time_epoch = 0.0;
		tsv::to_number(row[tc.i.com.time_epoch], time_epoch);
		m_reorder.push(time_epoch, std::move(buffered_line));
		m_reorder.flush_ready([this, &tc](std::string_view ordered_line) {
			process_ordered_line(tc, ordered_line);
		});
	}

	m_reorder.flush_all([this, &tc](std::string_view ordered_line) {
		process_ordered_line(tc, ordered_line);
	});

	return 0;
}

int monitor::process_ordered_line(tsv::ctx &tc, std::string_view line) {
	tsv::row_t row;
	tsv::split(line, row);

	const packet_context packet = make_packet_context(tc, row);
	if(packet.dispatch_proto_changed()) {
		trace(4, "monitor: effective proto %s -> %s method=%s uri=%s status=%s",
		      packet.proto.c_str(),
		      packet.dispatch_proto.c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.method)).c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.uri)).c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.status_code)).c_str());
	}

	m_interfaces->observe(packet.interface_id, packet.interface_name);

	m_streams->process_packet(tc, row, packet);

	auto br = m_second_boundary.update(packet.time_epoch);
	if(!br.changed) {
		return 0;
	}

	write_second_boundary_outputs(tc.r.com.time_epoch, packet);

	return 0;
}

void monitor::update_second_boundary_state(double now) {
	m_interfaces->process(now);
	m_streams->update_events(now);
	m_interfaces->update_events(now);
}

json monitor::build_metrics_root(double now, const packet_context &packet) {
	json::array_t metrics_list;
	m_streams->append_metrics(now, metrics_list);

	json::array_t interface_metrics;
	m_interfaces->append_metrics(now, interface_metrics);

	json root{
		{"time", now},
		{"metrics", std::move(metrics_list)},
		{"interfaces", std::move(interface_metrics)},
	};
	if(packet.vlan.empty() == false) {
		root["vlan"] = tsv::to_json(packet.vlan);
	}

	return root;
}

void monitor::evaluate_alerts(double now, const json &metrics_root) {
	if(!m_alerts || m_alerts->empty()) return;
	m_alerts->evaluate(now,
	                   metrics_root.at("metrics").get<json::array_t>(),
	                   metrics_root.at("interfaces").get<json::array_t>());
}

void monitor::write_second_boundary_outputs(double now, const packet_context &packet) {
	update_second_boundary_state(now);
	auto metrics_root = build_metrics_root(now, packet);
	evaluate_alerts(now, metrics_root);
	m_logs->append_metrics_snapshot(metrics_root);
}
