std::string metric_sample_projector::target_key(const json &entry, bool is_interface) {
	if(is_interface) {
		if(entry.contains("interface_id") && entry.at("interface_id").is_number_integer()) {
			return "interface:" + std::to_string(entry.at("interface_id").get<int>());
		}
		if(entry.contains("name") && entry.at("name").is_string()) {
			return "interface:name:" + entry.at("name").get<std::string>();
		}
		return "interface:unknown";
	}

	const auto stream_key = entry.value("stream_key", std::string{});
	const auto flow_key = entry.value("flow_key", std::string{});
	if(flow_key.empty()) return "stream:" + stream_key;
	return "flow:" + stream_key + "::" + flow_key;
}

json metric_sample_projector::make_target(const json &entry, bool is_interface) {
	const auto key = target_key(entry, is_interface);
	json target{
		{"kind", is_interface ? "interface" : (entry.value("flow_key", std::string{}).empty() ? "stream" : "flow")},
		{"key", key},
		{"scope", entry.value("scope", json::object())},
	};

	if(is_interface) {
		if(entry.contains("interface_id")) target["interface_id"] = entry["interface_id"];
		if(entry.contains("name")) target["interface_name"] = entry["name"];
		if(entry.contains("link")) target["link"] = entry["link"];
		return target;
	}

	if(entry.contains("stream_key")) target["stream_key"] = entry["stream_key"];
	if(entry.contains("flow_key") && entry["flow_key"].is_string() && !entry["flow_key"].get<std::string>().empty()) {
		target["flow_key"] = entry["flow_key"];
	}
	if(entry.contains("proto")) target["proto"] = entry["proto"];
	if(entry.contains("role")) target["role"] = entry["role"];
	if(entry.contains("endpoint")) target["endpoint"] = entry["endpoint"];
	if(entry.contains("interface_id")) target["interface_id"] = entry["interface_id"];
	if(entry.contains("interface_name")) target["interface_name"] = entry["interface_name"];
	return target;
}

bool metric_sample_projector::is_stat_object(const json &value) {
	if(!value.is_object()) return false;
	static const char *keys[] = {"value", "avg", "min", "max", "count", "bps", "pps", "seconds", "total", "window"};
	for(const char *key : keys) {
		if(value.contains(key) && value.at(key).is_number()) return true;
	}
	return false;
}

json metric_sample_projector::make_template(const json &value) {
	if(value.is_array()) return json::array();
	if(is_stat_object(value)) return nullptr;
	if(!value.is_object()) return value;

	json out = json::object();
	for(auto it = value.begin(); it != value.end(); ++it) {
		const json child = make_template(it.value());
		if(child.is_null()) continue;
		if(child.is_object() && child.empty()) continue;
		if(child.is_array() && child.empty()) continue;
		out[it.key()] = child;
	}
	return out;
}

double metric_sample_projector::first_stat_value(const json &record) {
	static const char *keys[] = {"value", "bps", "pps", "seconds", "total", "window", "avg", "min", "max"};
	for(const char *key : keys) {
		if(record.contains(key) && record.at(key).is_number()) return record.at(key).get<double>();
	}
	return 0.0;
}

void metric_sample_projector::collect_values(const std::string &prefix,
                                             const json &value,
                                             std::map<std::string, double> &out) {
	if(is_stat_object(value)) {
		out[prefix] = first_stat_value(value);
		return;
	}
	if(value.is_number()) {
		out[prefix] = value.get<double>();
		return;
	}
	if(!value.is_object() || value.is_array()) return;
	for(auto it = value.begin(); it != value.end(); ++it) {
		const auto child_prefix = prefix.empty() ? it.key() : prefix + "." + it.key();
		collect_values(child_prefix, it.value(), out);
	}
}

void metric_sample_projector::set_path(json &out, const std::string &path, json value) {
	json *cursor = &out;
	std::size_t start = 0;
	while(true) {
		const std::size_t dot = path.find('.', start);
		const auto part = path.substr(start, dot == std::string::npos ? std::string::npos : dot - start);
		if(dot == std::string::npos) {
			(*cursor)[part] = std::move(value);
			return;
		}
		if(!cursor->contains(part) || !(*cursor)[part].is_object()) (*cursor)[part] = json::object();
		cursor = &(*cursor)[part];
		start = dot + 1;
	}
}

