  const metricKeys = new Set<string>();

  for (const file of listSampleFiles(resolution, options.from, options.to)) {
    await readSampleFile(file, (sample) => {
      const entry = sample.metric;
      if (!entry || entry.time < options.from || entry.time > options.to || entry.streamKey !== options.streamKey) return;
      const flow = ensureFlowSeries(flows, entry);
      for (const [metricKey, stat] of Object.entries(entry.metrics)) {
        metricKeys.add(metricKey);
        flow.metrics[metricKey] ??= {
          key: metricKey,
          label: descriptorForMetric(metricKey).label,
          unit: descriptorForMetric(metricKey).unit,
          points: []
        };
        flow.metrics[metricKey].points.push({ time: sample.time, ...stat });
      }
    });
  }

  const orderedFlows = [...flows.values()].sort((a, b) => a.label.localeCompare(b.label) || a.flowKey.localeCompare(b.flowKey));
  for (const flow of orderedFlows) {
    for (const metric of Object.values(flow.metrics)) metric.points.sort((a, b) => a.time - b.time);
  }
  const streamBitrate = buildStreamBitrate(orderedFlows);
  if (streamBitrate.points.length > 0) metricKeys.add("bitrate");

  const descriptors = [...metricKeys]
    .map(descriptorForMetric)
    .sort((a, b) => a.priority - b.priority || a.label.localeCompare(b.label));

  return {
    streamKey: options.streamKey,
    windowSec: Math.max(1, options.to - options.from),
    streamBitrate,
    flows: orderedFlows.map((flow) => ({
      flowKey: flow.flowKey,
      role: flow.role,
      label: flow.label,
      endpointSrc: flow.endpointSrc,
      endpointDst: flow.endpointDst,
      metrics: flow.metrics
    })),
    descriptors
  };
}

