export async function queryMetricsSnapshotAt(time: number): Promise<{ interfaces: NormalizedInterfaceInput[]; metrics: NormalizedMetricInput[] } | undefined> {
  let latestTime = Number.NEGATIVE_INFINITY;
  const interfaces = new Map<string, NormalizedInterfaceInput>();
  const metrics = new Map<string, NormalizedMetricInput>();
  for (const file of listSampleFiles("1s", Math.max(0, time - 3600), time)) {
    await readSampleFile(file, (sample) => {
      if (sample.time > time || sample.time < latestTime) return;
      if (sample.time > latestTime) {
        latestTime = sample.time;
        interfaces.clear();
        metrics.clear();
      }
      if (sample.interface) interfaces.set(sample.targetKey, sample.interface);
      if (sample.metric) metrics.set(sample.targetKey, sample.metric);
    });
  }
  if (!Number.isFinite(latestTime)) return undefined;
  return { interfaces: [...interfaces.values()], metrics: [...metrics.values()] };
}

export async function queryInterfaceMetricsHistory(options: { key: string; from: number; to: number }): Promise<InterfaceMetricsResponse | undefined> {
  const points: Array<{ time: number; metrics: Record<string, NumericStat> }> = [];
  let latest: NormalizedInterfaceInput | undefined;
  for (const file of listSampleFiles("1s", options.from, options.to)) {
    await readSampleFile(file, (sample) => {
      const item = sample.interface;
      if (!item || item.key !== options.key || sample.time < options.from || sample.time > options.to) return;
      latest = item;
      points.push({ time: sample.time, metrics: interfaceMetrics(item) });
    });
  }
  if (!latest) return undefined;
  return {
    key: latest.key,
    interfaceId: latest.interfaceId,
    name: latest.name,
    windowSec: Math.max(1, options.to - options.from),
    metrics: buildMetricSeries(points)
  };
}

export async function queryStreamMetricsHistory(options: QueryOptions): Promise<StreamMetricsResponse> {
  const resolution = selectResolution(options);
  const flows = new Map<string, FlowSeries>();
  const metricKeys = new Set<string>();

  for (const file of listSampleFiles(resolution, options.from, options.to)) {
    await readSampleFile(file, (sample) => {
      const entry = sample.metric;
      if (!entry || entry.time < options.from || entry.time > options.to || entry.streamKey !== options.streamKey) return;
      const flow = ensureFlowSeries(flows, entry);
      for (const [metricKey, stat] of Object.entries(entry.metrics)) {
        metricKeys.add(metricKey);
        flow.metrics[metricKey] ??= {
          key: metricKey,
          label: descriptorForMetric(metricKey).label,
          unit: descriptorForMetric(metricKey).unit,
          points: []
        };
        flow.metrics[metricKey].points.push({ time: sample.time, ...stat });
      }
    });
  }

  const orderedFlows = [...flows.values()].sort((a, b) => a.label.localeCompare(b.label) || a.flowKey.localeCompare(b.flowKey));
  for (const flow of orderedFlows) {
    for (const metric of Object.values(flow.metrics)) metric.points.sort((a, b) => a.time - b.time);
  }
  const streamBitrate = buildStreamBitrate(orderedFlows);
  if (streamBitrate.points.length > 0) metricKeys.add("bitrate");

  const descriptors = [...metricKeys]
    .map(descriptorForMetric)
    .sort((a, b) => a.priority - b.priority || a.label.localeCompare(b.label));

  return {
    streamKey: options.streamKey,
    windowSec: Math.max(1, options.to - options.from),
    streamBitrate,
    flows: orderedFlows.map((flow) => ({
      flowKey: flow.flowKey,
      role: flow.role,
      label: flow.label,
      endpointSrc: flow.endpointSrc,
      endpointDst: flow.endpointDst,
      metrics: flow.metrics
    })),
    descriptors
  };
}

function interfaceMetrics(item: NormalizedInterfaceInput): Record<string, NumericStat> {
  const metrics: Record<string, NumericStat> = {
    "rx.bitrate": item.rxBitrate,
    "tx.bitrate": item.txBitrate,
    "rx.packets": item.rx.packets,
    "tx.packets": item.tx.packets,
    "rx.errors": item.rx.errors,
    "tx.errors": item.tx.errors,
    "rx.dropped": item.rx.dropped,
    "tx.dropped": item.tx.dropped
  };
  if (item.rxRate?.utilization !== undefined) metrics["rx.utilization"] = scalarMetric(item.rxRate.utilization);
  if (item.txRate?.utilization !== undefined) metrics["tx.utilization"] = scalarMetric(item.txRate.utilization);
  if (item.rxRate?.headroomBps !== undefined) metrics["rx.headroom"] = scalarMetric(item.rxRate.headroomBps);
  if (item.txRate?.headroomBps !== undefined) metrics["tx.headroom"] = scalarMetric(item.txRate.headroomBps);
  return metrics;
}

function scalarMetric(value: number): NumericStat { return { value, avg: value, min: value, max: value }; }

