	, m_metrics(m_cfg.metrics_journal_dir) {
	if(m_cfg.state_file.empty()) {
		m_cfg.state_file = m_cfg.output_dir / "projector-state.json";
	}
	std::filesystem::create_directories(m_cfg.output_dir);
	m_timeline_writer = std::make_unique<writer>("STM_PROJECTOR_TIMELINE",
	                                            (m_cfg.output_dir / "timeline" / "live.ndjson").string(),
