int stm_projector::project_metrics(const json &record) {
	if(!record.is_object() || record.value("record_type", std::string{}) != "metrics_snapshot") {
		return 0;
	}
	const double time = record.value("time", 0.0);
	if(time <= 0.0 || !record.contains("metrics") || !record["metrics"].is_array() ||
	   !record.contains("interfaces") || !record["interfaces"].is_array()) {
		return 0;
	}
	m_current_metrics = record["metrics"].get<json::array_t>();
	m_current_interfaces = record["interfaces"].get<json::array_t>();
	m_last_metrics_record_id = record.value("record_id", std::string{});
	m_metrics_projector->append_snapshot(time, m_current_metrics, m_current_interfaces, record);
	write_topology(time, record);
	return 0;
}

void stm_projector::write_topology(double time, const json &source_record) {
	if(!m_topology_writer || !m_topology_projector || !m_stream_state) return;
	json::array_t alerts;
	for(const auto &[_, alert] : m_active_alerts.items()) alerts.push_back(alert);
	const auto streams = m_stream_state->snapshot(time).value("streams", json::array_t{});
	const auto topology = m_topology_projector->build(time, streams, m_current_interfaces, m_current_metrics, alerts);
	int run_follow();

private:
	config m_cfg;
	journal_reader m_events;
	journal_reader m_metrics;
	journal_reader::cursor m_event_cursor;
	journal_reader::cursor m_metrics_cursor;
	std::unique_ptr<writer> m_timeline_writer;
	std::unique_ptr<timeline_sink> m_timeline_sink;
	std::unique_ptr<timeline_projector> m_timeline_projector;
	std::unique_ptr<time_rotating_writer> m_timeline_availability_writer;
	std::unique_ptr<metric_sample_projector> m_metrics_projector;
	std::unique_ptr<stream_state_projector> m_stream_state;
	std::unique_ptr<topology_projector> m_topology_projector;
	std::unique_ptr<topology_state_projector> m_topology_state;
	std::unique_ptr<writer> m_topology_writer;
	std::unique_ptr<time_rotating_writer> m_topology_events_writer;
	json::array_t m_current_metrics;
	json::array_t m_current_interfaces;
	json m_active_alerts = json::object();
	std::string m_last_event_record_id;
	std::string m_last_metrics_record_id;

	void load_state();
	void save_state() const;
	int project_event(const json &record);
	int project_metrics(const json &record);
	void write_topology(double time, const json &source);
	void write_topology_event(const json &event);
};

