      time?: number;
      active_rows?: Array<{
        key?: string;
        type?: string;
        stream_key?: string;
        flow_key?: string;
        proto?: string;
        role?: string;
        label?: string;
        interface_id?: number | null;
        first_seen?: number;
        last_seen?: number;
