import { createReadStream, existsSync, readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import readline from "node:readline";
import { config } from "../config";
import { normalizeTimelineLine, type NormalizedTimelineInput } from "../normalizer";
import type { TimelineRow, TimelineViewResponse, TimelineWindow } from "../types";

type QueryOptions = {
  from: number;
  to: number;
  includeFlows?: boolean;
};

type TimelineCheckpoint = {
  time: number;
  rows: Map<string, TimelineRow>;
};

export async function queryTimelineHistory(options: QueryOptions): Promise<TimelineViewResponse> {
  const available = getTimelineAvailableWindow() ?? { from: options.from, to: options.to };
  const checkpoint = loadLatestTimelineCheckpoint(options.from, options.includeFlows ?? true);
  const seedFrom = Math.max(0, checkpoint?.time ?? available.from);
  const files = listTimelineFiles(seedFrom, options.to);
  const rows = checkpoint?.rows ?? new Map<string, TimelineRow>();

  for (const file of files) {
    await readTimelineFile(file, (item) => {
      if (item.time < seedFrom) return;
      if (item.time > options.to) return;
      if (!options.includeFlows && item.subjectType === "flow") return;
      applyTimelineEvent(rows, item);
    });
  }

  const clipped = [...rows.values()]
    .map((row) => clipTimelineRow(row, options.from, options.to))
    .filter((row): row is TimelineRow => row !== undefined);

  const streamByKey = new Map<string, TimelineRow>();
  for (const row of clipped) {
    if (row.rowType === "stream") streamByKey.set(row.streamKey, row);
  }

  for (const row of clipped) {
    if (row.rowType !== "flow" || !row.parentStreamKey) continue;
    if (streamByKey.has(row.parentStreamKey)) continue;
    const originalParent = rows.get(row.parentStreamKey);
    if (!originalParent) continue;
    const fallback: TimelineRow = {
      ...originalParent,
      rowType: "stream",
      flowKey: undefined,
      parentStreamKey: undefined,
      active: row.active,
      firstSeen: row.firstSeen,
      lastSeen: row.lastSeen,
      // stream自体の帯が範囲外でも、flowが見えている間は親ラベル行を残す
      segments: []
    };
    clipped.push(fallback);
    streamByKey.set(fallback.streamKey, fallback);
  }

  const timelineRows = clipped.sort((a, b) => {
      if (a.interfaceId !== undefined || b.interfaceId !== undefined) {
        if (a.interfaceId === undefined) return 1;
        if (b.interfaceId === undefined) return -1;
        if (a.interfaceId !== b.interfaceId) return a.interfaceId - b.interfaceId;
      }
      const parentA = a.parentStreamKey ?? a.streamKey;
      const parentB = b.parentStreamKey ?? b.streamKey;
      if (parentA !== parentB) return parentA.localeCompare(parentB);
      if (a.rowType !== b.rowType) return a.rowType === "stream" ? -1 : 1;
      return (a.flowKey ?? a.streamKey).localeCompare(b.flowKey ?? b.streamKey);
    });

  return {
    rows: timelineRows,
    window: { from: options.from, to: options.to },
    available,
    source: "history"
  };
}

function loadLatestTimelineCheckpoint(from: number, includeFlows: boolean): TimelineCheckpoint | undefined {
  const checkpointRoot = config.timelineCheckpointDir;
  if (!existsSync(checkpointRoot)) return undefined;

  const dayDirs = readdirSync(checkpointRoot, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && /^\d{8}$/.test(entry.name))
    .map((entry) => entry.name)
    .sort();
  if (dayDirs.length === 0) return undefined;

  const candidates: Array<{ ts: number; file: string }> = [];
  for (const dayDir of dayDirs) {
    const year = Number(dayDir.slice(0, 4));
