import { existsSync } from "node:fs";
import path from "node:path";

const rootDir = resolveRootDir();
const argv = parseArgs(process.argv.slice(2));
const logDir = path.resolve(rootDir, String(argv.logDir ?? process.env.LOG_DIR ?? "."));
const derivedDirInput = resolveDirValue(argv.derivedDir ?? process.env.DERIVED_DIR ?? "derived", "derived");
const derivedDir = resolveDirPath(logDir, derivedDirInput);
const derivedPath = (...segments: string[]) => path.join(derivedDir, ...segments);

const eventJournalDirInput = resolveDirValue(
  argv.eventJournalDir ?? process.env.EVENT_JOURNAL_DIR ?? "event-journal", "event journal"
);
const streamStateDirInput = resolveDirValue(
  argv.streamStateDir ?? process.env.STREAM_STATE_DIR ?? derivedPath("streams"), "stream state"
);
const metricsSamples1sDirInput = resolveDirValue(
  argv.metricsSamples1sDir ?? process.env.METRICS_SAMPLES_1S_DIR ?? derivedPath("metrics", "samples", "1s"), "one-second metric samples"
);
const metricsSamples1mDirInput = resolveDirValue(
  argv.metricsSamples1mDir ?? process.env.METRICS_SAMPLES_1M_DIR ?? derivedPath("metrics", "samples", "1m"), "one-minute metric samples"
);
const timelineEventsDirInput = resolveDirValue(
  argv.timelineEventsDir ?? process.env.TIMELINE_EVENTS_DIR ?? derivedPath("timeline", "events"), "timeline events"
);
const timelineCheckpointDirInput = resolveDirValue(
  argv.timelineCheckpointDir ?? process.env.TIMELINE_CHECKPOINT_DIR ?? derivedPath("timeline", "checkpoint"), "timeline checkpoint"
);
const topologyCheckpointDirInput = resolveDirValue(
  argv.topologyCheckpointDir ?? process.env.TOPOLOGY_CHECKPOINT_DIR ?? derivedPath("topology", "checkpoint"), "topology checkpoint"
);
const topologyUpdatesDirInput = resolveDirValue(
  argv.topologyUpdatesDir ?? process.env.TOPOLOGY_UPDATES_DIR ?? derivedPath("topology", "updates"), "topology updates"
);
const timelineLiveFile = resolveFilePath(logDir, argv.timelineLiveFile ?? process.env.TIMELINE_LIVE_FILE ?? derivedPath("timeline", "live.ndjson"), "timeline live");
const topologyLiveFile = resolveFilePath(logDir, argv.topologyLiveFile ?? process.env.TOPOLOGY_LIVE_FILE ?? derivedPath("topology", "live.ndjson"), "topology live");
const stmConfigFile = optionalFilePath(argv.stmConfigFile ?? process.env.STM_CONFIG_FILE);

export const config = {
  host: String(argv.host ?? process.env.HOST ?? "0.0.0.0"),
  port: Number(argv.port ?? process.env.PORT ?? 3000),
  rootDir,
  logDir,
  derivedDir,
  eventJournalDir: resolveDirPath(logDir, eventJournalDirInput),
  streamStateDir: resolveDirPath(logDir, streamStateDirInput),
  metricsSamples1sDir: resolveDirPath(logDir, metricsSamples1sDirInput),
  metricsSamples1mDir: resolveDirPath(logDir, metricsSamples1mDirInput),
  timelineLiveFile,
  timelineEventsDir: resolveDirPath(logDir, timelineEventsDirInput),
  timelineCheckpointDir: resolveDirPath(logDir, timelineCheckpointDirInput),
  topologyLiveFile,
  topologyCheckpointDir: resolveDirPath(logDir, topologyCheckpointDirInput),
  topologyUpdatesDir: resolveDirPath(logDir, topologyUpdatesDirInput),
  stmConfigFile,
  historyWindowSec: Number(process.env.HISTORY_WINDOW_SEC ?? 300),
  timelineWindowSec: Number(process.env.TIMELINE_WINDOW_SEC ?? 3600),
  staleAfterSec: Number(process.env.STALE_AFTER_SEC ?? 5),
  lostRetentionSec: Number(process.env.LOST_RETENTION_SEC ?? 30),
  pollMs: Number(process.env.LOG_POLL_MS ?? 500),
  streamsPatchIntervalMs: Number(argv.streamsPatchIntervalMs ?? process.env.STREAMS_PATCH_INTERVAL_MS ?? 250),
  wsMaxBufferedBytes: Number(argv.wsMaxBufferedBytes ?? process.env.WS_MAX_BUFFERED_BYTES ?? 8 * 1024 * 1024),
  maxEvents: Number(argv.maxEvents ?? process.env.MAX_EVENTS ?? 1000),
  maxTimelineRows: Number(argv.maxTimelineRows ?? process.env.MAX_TIMELINE_ROWS ?? 20000),
  httpAccessLog: toBool(argv.httpAccessLog ?? process.env.HTTP_ACCESS_LOG, false),
  metricsChunkLog: toBool(argv.metricsChunkLog ?? process.env.METRICS_CHUNK_LOG, false),
  eventsQueryDebugLog: toBool(argv.eventsQueryDebugLog ?? process.env.EVENTS_QUERY_DEBUG_LOG, false),
  diagnosticLog: toBool(argv.diagnosticLog ?? process.env.STM_DIAGNOSTIC_LOG, false),
  clientDist: path.resolve(rootDir, "client/dist"),
  dashboardLayoutsFile: path.resolve(rootDir, "dashboard-layouts.json"),
  maintenanceSettingsFile: path.resolve(rootDir, "maintenance-settings.json"),
  runtimeSettingsFile: path.resolve(rootDir, "runtime-settings.json")
};

/** Projected inputs can be absent while STM/projector are starting. */
export function ensureLogFilesExist() {}

function resolveDirValue(value: unknown, label: string) {
  const dirName = String(value ?? "").trim();
  if (!dirName) throw new Error(`missing ${label} directory`);
  return dirName;
}
function resolveDirPath(baseDir: string, dirValue: string) { return path.isAbsolute(dirValue) ? dirValue : path.resolve(baseDir, dirValue); }
function optionalFilePath(value: unknown) {
  const file = String(value ?? "").trim();
  return file ? path.resolve(rootDir, file) : undefined;
}
function resolveFilePath(baseDir: string, value: unknown, label: string) {
  const file = String(value ?? "").trim();
  if (!file) throw new Error(`missing ${label} file`);
  return path.isAbsolute(file) ? file : path.resolve(baseDir, file);
}
function resolveRootDir() {
  const cwd = process.cwd();
  if (path.basename(cwd) === "server" && existsSync(path.join(cwd, "package.json"))) return path.resolve(cwd, "..");
  if (existsSync(path.join(cwd, "client", "package.json")) && existsSync(path.join(cwd, "server", "package.json"))) return cwd;
  if (existsSync(path.join(cwd, "fe", "client", "package.json")) && existsSync(path.join(cwd, "fe", "server", "package.json"))) return path.join(cwd, "fe");
  if (existsSync(path.join(cwd, "server", "package.json"))) return cwd;
  return path.resolve(cwd, "..");
}
function parseArgs(args: string[]) {
  const parsed: Record<string, string> = {};
  const aliases: Record<string, string> = {
    "log-dir": "logDir", "derived-dir": "derivedDir", "event-journal-dir": "eventJournalDir", "stream-state-dir": "streamStateDir",
    "timeline-live-file": "timelineLiveFile", "timeline-events-dir": "timelineEventsDir", "timeline-checkpoint-dir": "timelineCheckpointDir",
    "metrics-samples-1s-dir": "metricsSamples1sDir", "metrics-samples-1m-dir": "metricsSamples1mDir",
    "topology-live-file": "topologyLiveFile", "topology-checkpoint-dir": "topologyCheckpointDir", "topology-updates-dir": "topologyUpdatesDir",
    "host": "host", "port": "port", "max-events": "maxEvents", "max-timeline-rows": "maxTimelineRows", "streams-patch-interval-ms": "streamsPatchIntervalMs",
    "ws-max-buffered-bytes": "wsMaxBufferedBytes", "stm-config-file": "stmConfigFile", "http-access-log": "httpAccessLog", "metrics-chunk-log": "metricsChunkLog", "events-query-debug-log": "eventsQueryDebugLog", "diagnostic-log": "diagnosticLog"
  };
  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];
    if (!arg.startsWith("--")) continue;
    const [rawKey, ...rest] = arg.slice(2).split("=");
    const inlineValue = rest.join("=");
    const value = inlineValue || (args[index + 1]?.startsWith("--") ? "" : args[index + 1] ?? "");
    const key = aliases[rawKey];
    if (!key || !value) continue;
    parsed[key] = value;
    if (!inlineValue) index += 1;
  }
  return parsed;
}
function toBool(value: unknown, defaultValue: boolean) {
  if (value === undefined || value === null || value === "") return defaultValue;
  const normalized = String(value).trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(normalized)) return true;
  if (["0", "false", "no", "off"].includes(normalized)) return false;
  return defaultValue;
}
import { createReadStream, existsSync, readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import readline from "node:readline";
import { config } from "../config";
import { normalizeTimelineLine, type NormalizedTimelineInput } from "../normalizer";
import type { TimelineRow, TimelineViewResponse, TimelineWindow } from "../types";

type QueryOptions = {
  from: number;
  to: number;
  includeFlows?: boolean;
};

type TimelineCheckpoint = {
  time: number;
  rows: Map<string, TimelineRow>;
};

export async function queryTimelineHistory(options: QueryOptions): Promise<TimelineViewResponse> {
  const available = getTimelineAvailableWindow() ?? { from: options.from, to: options.to };
  const checkpoint = loadLatestTimelineCheckpoint(options.from, options.includeFlows ?? true);
  const seedFrom = Math.max(0, checkpoint?.time ?? available.from);
  const files = listTimelineFiles(seedFrom, options.to);
  const rows = checkpoint?.rows ?? new Map<string, TimelineRow>();

  for (const file of files) {
    await readTimelineFile(file, (item) => {
      if (item.time < seedFrom) return;
      if (item.time > options.to) return;
      if (!options.includeFlows && item.subjectType === "flow") return;
      applyTimelineEvent(rows, item);
    });
  }

  const clipped = [...rows.values()]
    .map((row) => clipTimelineRow(row, options.from, options.to))
    .filter((row): row is TimelineRow => row !== undefined);

  const streamByKey = new Map<string, TimelineRow>();
  for (const row of clipped) {
    if (row.rowType === "stream") streamByKey.set(row.streamKey, row);
  }

  for (const row of clipped) {
    if (row.rowType !== "flow" || !row.parentStreamKey) continue;
    if (streamByKey.has(row.parentStreamKey)) continue;
    const originalParent = rows.get(row.parentStreamKey);
    if (!originalParent) continue;
    const fallback: TimelineRow = {
      ...originalParent,
      rowType: "stream",
      flowKey: undefined,
      parentStreamKey: undefined,
      active: row.active,
      firstSeen: row.firstSeen,
      lastSeen: row.lastSeen,
      // stream自体の帯が範囲外でも、flowが見えている間は親ラベル行を残す
      segments: []
    };
    clipped.push(fallback);
    streamByKey.set(fallback.streamKey, fallback);
  }

  const timelineRows = clipped.sort((a, b) => {
      if (a.interfaceId !== undefined || b.interfaceId !== undefined) {
        if (a.interfaceId === undefined) return 1;
        if (b.interfaceId === undefined) return -1;
        if (a.interfaceId !== b.interfaceId) return a.interfaceId - b.interfaceId;
      }
      const parentA = a.parentStreamKey ?? a.streamKey;
      const parentB = b.parentStreamKey ?? b.streamKey;
      if (parentA !== parentB) return parentA.localeCompare(parentB);
      if (a.rowType !== b.rowType) return a.rowType === "stream" ? -1 : 1;
      return (a.flowKey ?? a.streamKey).localeCompare(b.flowKey ?? b.streamKey);
    });

  return {
    rows: timelineRows,
    window: { from: options.from, to: options.to },
    available,
    source: "history"
  };
}

function loadLatestTimelineCheckpoint(from: number, includeFlows: boolean): TimelineCheckpoint | undefined {
  const checkpointRoot = config.timelineCheckpointDir;
  if (!existsSync(checkpointRoot)) return undefined;

  const dayDirs = readdirSync(checkpointRoot, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && /^\d{8}$/.test(entry.name))
    .map((entry) => entry.name)
    .sort();
  if (dayDirs.length === 0) return undefined;

  const candidates: Array<{ ts: number; file: string }> = [];
  for (const dayDir of dayDirs) {
    const year = Number(dayDir.slice(0, 4));
    const month = Number(dayDir.slice(4, 6)) - 1;
    const day = Number(dayDir.slice(6, 8));
    const dirPath = path.join(checkpointRoot, dayDir);
    const files = readdirSync(dirPath, { withFileTypes: true })
      .filter((entry) => entry.isFile() && /^\d{4}\.json$/.test(entry.name))
      .map((entry) => entry.name);
    for (const fileName of files) {
      const hour = Number(fileName.slice(0, 2));
      const minute = Number(fileName.slice(2, 4));
      const ts = Date.UTC(year, month, day, hour, minute, 0) / 1000;
      if (ts <= from) {
        candidates.push({ ts, file: path.join(dirPath, fileName) });
      }
    }
  }

  if (candidates.length === 0) return undefined;
  candidates.sort((a, b) => b.ts - a.ts);
  const selected = candidates[0];

  try {
    const text = readFileSync(selected.file, "utf8").trim();
    if (!text) return undefined;
    const parsed = JSON.parse(text) as {
      time?: number;
      active_rows?: Array<{
        key?: string;
        type?: string;
        stream_key?: string;
        flow_key?: string;
        proto?: string;
        role?: string;
        label?: string;
        interface_id?: number | null;
        first_seen?: number;
        last_seen?: number;
        subject?: Record<string, unknown>;
      }>;
    };
    const rows = new Map<string, TimelineRow>();
    const snapshotTime = Number.isFinite(parsed.time) ? Number(parsed.time) : selected.ts;
    for (const item of parsed.active_rows ?? []) {
      const rowType = item.type === "flow" ? "flow" : "stream";
      if (!includeFlows && rowType === "flow") continue;
      const streamKey = item.stream_key ?? "";
      if (!streamKey) continue;
      const flowKey = item.flow_key ?? undefined;
      const key = item.key ?? (rowType === "flow" ? `${streamKey}::${flowKey ?? ""}` : streamKey);
      const subject = item.subject ?? {};
      const interfaceIdRaw = typeof item.interface_id === "number" ? item.interface_id : undefined;
      const normalized = normalizeTimelineLine(JSON.stringify({
        time: snapshotTime,
        kind: rowType === "flow" ? "flow_detected" : "stream_detected",
        subject
      }));

      const row: TimelineRow = {
        rowType,
        streamKey,
        flowKey,
        parentStreamKey: rowType === "flow" ? streamKey : undefined,
        kind: normalized?.proto ?? item.proto ?? "",
        proto: normalized?.proto ?? item.proto ?? "",
        label: normalized?.label ?? item.label ?? streamKey,
        role: normalized?.role ?? item.role ?? undefined,
        endpointSrc: normalized?.endpointSrc ?? readEndpoint(subject, "src"),
        endpointDst: normalized?.endpointDst ?? readEndpoint(subject, "dst"),
        interfaceId: normalized?.interfaceId ?? interfaceIdRaw,
        interfaceName: normalized?.interfaceName,
        scope: normalized?.scope,
        active: true,
        firstSeen: Number.isFinite(item.first_seen) ? Number(item.first_seen) : snapshotTime,
        lastSeen: Number.isFinite(item.last_seen) ? Number(item.last_seen) : snapshotTime,
        segments: [{ start: Math.min(from, snapshotTime), end: null }]
      };
      rows.set(key, row);
    }
    return { time: selected.ts, rows };
  } catch {
    return undefined;
  }
}

function readEndpoint(subject: Record<string, unknown>, field: "src" | "dst") {
  const endpoint = subject.endpoint;
  if (!endpoint || typeof endpoint !== "object") return undefined;
  const value = (endpoint as Record<string, unknown>)[field];
  return typeof value === "string" ? value : undefined;
}

function timelineKey(input: NormalizedTimelineInput) {
  return input.subjectType === "flow" ? `${input.streamKey}::${input.flowKey ?? ""}` : input.streamKey;
}

function ensureTimelineRow(rows: Map<string, TimelineRow>, input: NormalizedTimelineInput) {
  const key = timelineKey(input);
  const existing = rows.get(key);
  if (existing) {
    existing.interfaceId = input.interfaceId ?? existing.interfaceId;
    existing.interfaceName = input.interfaceName ?? existing.interfaceName;
    existing.kind = input.proto;
    existing.proto = input.proto;
    existing.label = input.label || existing.label;
    existing.role = input.role ?? existing.role;
    existing.endpointSrc = input.endpointSrc ?? existing.endpointSrc;
    existing.endpointDst = input.endpointDst ?? existing.endpointDst;
    existing.scope = input.scope.known ? input.scope : existing.scope;
    return existing;
  }

  const created: TimelineRow = {
    rowType: input.subjectType === "flow" ? "flow" : "stream",
    streamKey: input.streamKey,
    flowKey: input.flowKey,
    parentStreamKey: input.subjectType === "flow" ? input.streamKey : undefined,
    kind: input.proto,
    proto: input.proto,
    label: input.label,
    role: input.role,
    endpointSrc: input.endpointSrc,
    endpointDst: input.endpointDst,
    interfaceId: input.interfaceId,
    interfaceName: input.interfaceName,
    scope: input.scope,
    active: false,
    firstSeen: input.time,
    lastSeen: input.time,
    segments: []
  };
  rows.set(key, created);
  return created;
}

function applyTimelineEvent(rows: Map<string, TimelineRow>, input: NormalizedTimelineInput) {
  const row = ensureTimelineRow(rows, input);
  row.firstSeen = Math.min(row.firstSeen, input.time);
  row.lastSeen = Math.max(row.lastSeen, input.time);

  if (input.kind === "stream_detected" || input.kind === "stream_recovered" || input.kind === "flow_detected" || input.kind === "flow_recovered") {
    row.active = true;
    const current = row.segments[row.segments.length - 1];
    if (!current || current.end !== null) {
      row.segments.push({ start: input.time, end: null });
    }
    return;
  }

  if (input.kind === "stream_lost" || input.kind === "flow_lost") {
    row.active = false;
    const current = row.segments[row.segments.length - 1];
    if (current && current.end === null) {
      current.end = input.time;
    } else if (!current) {
      row.segments.push({ start: input.time, end: input.time });
    }
  }
}

function clipTimelineRow(row: TimelineRow, from: number, to: number): TimelineRow | undefined {
  const clippedSegments = row.segments
    .map((segment) => {
      const effectiveEnd = segment.end ?? to;
      if (effectiveEnd <= from || segment.start >= to) return undefined;
      return {
        start: Math.max(segment.start, from),
        end: segment.end === null ? null : Math.min(segment.end, to)
      };
    })
    .filter((segment): segment is NonNullable<typeof segment> => segment !== undefined);

  if (clippedSegments.length === 0) {
    return undefined;
  }

  return {
    ...row,
    firstSeen: clippedSegments[0].start,
    lastSeen: Math.min(row.lastSeen, to),
    segments: clippedSegments
  };
}

function listTimelineFiles(from: number, to: number) {
  const files: string[] = [];
  const current = new Date(Math.floor(from) * 1000);
