      current.setUTCHours(current.getUTCHours() + 1);
    }
  }

  return files;
}

function filePartIndex(name: string) {
  const m = name.match(/\.part(\d+)\.ndjson$/);
  if (!m) return 0;
  return Number(m[1]) || 0;
}
