 36	    .map((row) => clipTimelineRow(row, options.from, options.to))
 37	    .filter((row): row is TimelineRow => row !== undefined);
 38	
 39	  const streamByKey = new Map<string, TimelineRow>();
 40	  for (const row of clipped) {
 41	    if (row.rowType === "stream") streamByKey.set(row.streamKey, row);
 42	  }
