20	export async function queryTimelineHistory(options: QueryOptions): Promise<TimelineViewResponse> {
21	  const available = getTimelineAvailableWindow() ?? { from: options.from, to: options.to };
22	  const checkpoint = loadLatestTimelineCheckpoint(options.from, options.includeFlows ?? true);
23	  const seedFrom = Math.max(0, checkpoint?.time ?? available.from);
24	  const files = listTimelineFiles(seedFrom, options.to);
25	  const rows = checkpoint?.rows ?? new Map<string, TimelineRow>();
26	
27	  for (const file of files) {
28	    await readTimelineFile(file, (item) => {
29	      if (item.time < seedFrom) return;
30	      if (item.time > options.to) return;
31	      if (!options.includeFlows && item.subjectType === "flow") return;
32	      applyTimelineEvent(rows, item);
33	    });
34	  }
35	
36	  const clipped = [...rows.values()]
37	    .map((row) => clipTimelineRow(row, options.from, options.to))
38	    .filter((row): row is TimelineRow => row !== undefined);
39	
40	  const streamByKey = new Map<string, TimelineRow>();
41	  for (const row of clipped) {
42	    if (row.rowType === "stream") streamByKey.set(row.streamKey, row);
43	  }
44	
45	  for (const row of clipped) {
46	    if (row.rowType !== "flow" || !row.parentStreamKey) continue;
47	    if (streamByKey.has(row.parentStreamKey)) continue;
48	    const originalParent = rows.get(row.parentStreamKey);
49	    if (!originalParent) continue;
50	    const fallback: TimelineRow = {
51	      ...originalParent,
52	      rowType: "stream",
53	      flowKey: undefined,
54	      parentStreamKey: undefined,
55	      active: row.active,
56	      firstSeen: row.firstSeen,
57	      lastSeen: row.lastSeen,
58	      // stream自体の帯が範囲外でも、flowが見えている間は親ラベル行を残す
59	      segments: []
60	    };
61	    clipped.push(fallback);
62	    streamByKey.set(fallback.streamKey, fallback);
63	  }
64	
65	  const timelineRows = clipped.sort((a, b) => {
66	      if (a.interfaceId !== undefined || b.interfaceId !== undefined) {
67	        if (a.interfaceId === undefined) return 1;
68	        if (b.interfaceId === undefined) return -1;
69	        if (a.interfaceId !== b.interfaceId) return a.interfaceId - b.interfaceId;
70	      }
71	      const parentA = a.parentStreamKey ?? a.streamKey;
72	      const parentB = b.parentStreamKey ?? b.streamKey;
73	      if (parentA !== parentB) return parentA.localeCompare(parentB);
74	      if (a.rowType !== b.rowType) return a.rowType === "stream" ? -1 : 1;
75	      return (a.flowKey ?? a.streamKey).localeCompare(b.flowKey ?? b.streamKey);
76	    });
77	
78	  return {
79	    rows: timelineRows,
80	    window: { from: options.from, to: options.to },
81	    available,
82	    source: "history"
83	  };
84	}
