const TIMELINE_QUERY_CHUNK_SEC = 30 * 60;
const TIMELINE_FOLLOW_REFRESH_MS = 5000;
const TIMELINE_DELTA_LOOKBACK_SEC = 120;
const STREAMS_PATCH_APPLY_MS = 2000;
const ENABLE_STREAMS_FULL_UPDATE = false;
const MAX_EVENTS_IN_MEMORY = 8000;

const limitEvents = (items: EventLogItem[]) => items.slice(0, MAX_EVENTS_IN_MEMORY);

export function useStreams(
  selectedStreamKey: string | null,
  selectedInterfaceKey: string | null,
  paused: boolean,
  selectedMetricsRange: string,
  selectedTimelineRange: string,
  selectedEventsRange: string,
  timelineFollowNow: boolean,
  manualTimelineWindowEndSec: number | null,
  streamSortRefreshToken: number,
  selectedTimeSec: number | null,
  onDefaultSelect?: (streamKey: string) => void,
  onConfigUpdate?: (config: import("../types/api").AppConfig) => void
