import { Fragment, useEffect, useMemo, useRef, useState } from "react";
import type { NetworkScope, TimelineRow } from "../types/api";
import { Icon } from "./ui/Icon";

type TimelinePaneProps = {
  rows: TimelineRow[];
  nowSec: number;
  fadeSec: number;
  rangeStartSec: number;
  rangeEndSec: number;
  expandLevel?: "interface" | "proto" | "stream" | "flow";
  selectedTimeSec?: number | null;
  onSelectTime?: (timeSec: number) => void;
  interfaceNames?: ReadonlyMap<number, string>;
};

type TimelineStreamGroup = { stream: TimelineRow; flows: TimelineRow[] };
type TimelineScopeGroup = {
  key: string;
  label: string;
  rows: TimelineStreamGroup[];
  segments: Array<{ start: number; end: number }>;
  active: boolean;
};
type TimelineProtoGroup = {
  key: string;
  proto: string;
  rows: TimelineStreamGroup[];
  segments: Array<{ start: number; end: number }>;
  active: boolean;
};

export function TimelinePane({ rows, nowSec, fadeSec, rangeStartSec, rangeEndSec, expandLevel = "stream", selectedTimeSec = null, onSelectTime, interfaceNames }: TimelinePaneProps) {
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const [interfaceExpanded, setInterfaceExpanded] = useState<Record<string, boolean>>({});
  const [scopeExpanded, setScopeExpanded] = useState<Record<string, boolean>>({});
  const [protoExpanded, setProtoExpanded] = useState<Record<string, boolean>>({});
  const axisScaleRef = useRef<HTMLDivElement | null>(null);
  const chartRef = useRef<HTMLDivElement | null>(null);
  const [cursorSec, setCursorSec] = useState(nowSec);
  const [isHoveringCursor, setIsHoveringCursor] = useState(false);
  const [hoveredRowKey, setHoveredRowKey] = useState<string | null>(null);
  const [viewport, setViewport] = useState({ top: 0, height: 480 });
  const cursorRafRef = useRef<number | null>(null);
  const pendingCursorXRef = useRef<number | null>(null);
  const hasAppliedExpandLevel = useRef(false);
  const previousExpandLevel = useRef<typeof expandLevel>(expandLevel);

  useEffect(() => {
    if (!isHoveringCursor) {
      setCursorSec(Math.min(rangeEndSec, Math.max(rangeStartSec, nowSec)));
    }
  }, [isHoveringCursor, nowSec, rangeStartSec, rangeEndSec]);

  const updateCursor = (clientX: number) => {
    const el = axisScaleRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0) return;
    const x = Math.min(rect.right, Math.max(rect.left, clientX));
    const ratio = (x - rect.left) / Math.max(1, rect.width);
    setCursorSec(range.start + ratio * (range.end - range.start));
  };

  const timeFromClientX = (clientX: number) => {
    const el = axisScaleRef.current;
    if (!el) return null;
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0) return null;
    const x = Math.min(rect.right, Math.max(rect.left, clientX));
    const ratio = (x - rect.left) / Math.max(1, rect.width);
    return range.start + ratio * (range.end - range.start);
  };

  useEffect(() => {
    setExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        if (row.rowType !== "stream") continue;
        if (!(row.streamKey in next)) {
          next[row.streamKey] = expandLevel === "flow";
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows, expandLevel, interfaceNames]);

  useEffect(() => {
    setInterfaceExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        const label = interfaceLabel(row, interfaceNames);
        const key = row.interfaceId !== undefined ? `if:${row.interfaceId}` : `name:${label}`;
        if (!(key in next)) {
          next[key] = expandLevel !== "interface";
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows, expandLevel]);

  useEffect(() => {
    setProtoExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        const ifKey = row.interfaceId !== undefined ? `if:${row.interfaceId}` : `name:${row.interfaceName ?? "unknown"}`;
        const proto = row.proto || row.kind || "OTHER";
        const key = `${ifKey}::${proto}`;
        if (!(key in next)) {
          next[key] = expandLevel === "stream" || expandLevel === "flow";
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows, expandLevel]);

  const range = useMemo(() => {
    const safeStart = Number.isFinite(rangeStartSec) ? rangeStartSec : nowSec - 60;
    const safeEnd = Number.isFinite(rangeEndSec) && rangeEndSec > safeStart ? rangeEndSec : safeStart + 1;
    const step = (safeEnd - safeStart) / 4;
    return {
      start: safeStart,
      end: safeEnd,
      ticks: Array.from({ length: 5 }, (_, index) => safeStart + step * index)
    };
  }, [nowSec, rangeStartSec, rangeEndSec]);
  const cursorPercent = percent(Math.min(range.end, Math.max(range.start, selectedTimeSec ?? cursorSec)), range.start, range.end);
  const cursorLabel = formatCursor(selectedTimeSec ?? cursorSec);

  const groupedRows = useMemo(() => {
    const streams = rows.filter((row) => row.rowType === "stream");
    const flowsByParent = new Map<string, TimelineRow[]>();
    for (const row of rows) {
      if (row.rowType !== "flow" || !row.parentStreamKey) continue;
      const group = flowsByParent.get(row.parentStreamKey) ?? [];
      group.push(row);
      flowsByParent.set(row.parentStreamKey, group);
    }
    return streams.map((stream) => {
      const flows = flowsByParent.get(stream.streamKey) ?? [];
      const flowScope = flows.find((flow) => flow.scope?.known)?.scope;
      const streamSegments = stream.segments.map((segment) => ({ start: segment.start, end: segment.end }));
      const flowSegments = flows.flatMap((flow) => flow.segments.map((segment) => ({ start: segment.start, end: segment.end })));
      const merged = mergeSegmentsNullable([...streamSegments, ...flowSegments]);
      return {
        stream: {
          ...stream,
          scope: stream.scope?.known ? stream.scope : flowScope ?? stream.scope,
          active: stream.active || flows.some((flow) => flow.active),
