  }, [rows]);

  const groupedByInterface = useMemo(() => {
    const groups = new Map<string, { key: string; label: string; rows: typeof groupedRows }>();
    for (const item of groupedRows) {
      const label = interfaceLabel(item.stream, interfaceNames);
      const key = item.stream.interfaceId !== undefined ? `if:${item.stream.interfaceId}` : `name:${label}`;
      const group = groups.get(key) ?? { key, label, rows: [] };
      group.rows.push(item);
      groups.set(key, group);
    }
    return [...groups.values()]
      .map((group) => ({
        ...group,
        segments: mergeSegments(
          group.rows.flatMap(({ stream }) => stream.segments.map((segment) => ({ start: segment.start, end: segment.end ?? rangeEndSec })))
        ),
        firstSeen: Math.min(...group.rows.map(({ stream }) => stream.firstSeen)),
        lastSeen: Math.max(...group.rows.map(({ stream }) => stream.lastSeen)),
