          nextProtos[protoGroup.key] = expandLevel === "stream" || expandLevel === "flow";
        }
      }
    }
    setScopeExpanded(nextScopes);
    setProtoExpanded(nextProtos);

    const nextStreams: Record<string, boolean> = {};
    for (const row of rows) {
      if (row.rowType === "stream") {
