      hasAppliedExpandLevel.current = true;
    }
  }, [expandLevel, groupedByInterface, range.end, rows]);

  useEffect(() => {
    return () => {
      if (cursorRafRef.current !== null) {
        window.cancelAnimationFrame(cursorRafRef.current);
        cursorRafRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    const chart = chartRef.current;
    if (!chart) return;
    const body = chart.closest(".timeline-body") as HTMLElement | null;
    if (!body) return;

    const update = () => {
      setViewport({
        top: body.scrollTop,
        height: body.clientHeight
      });
    };

    update();
    body.addEventListener("scroll", update, { passive: true });
    const observer = new ResizeObserver(update);
    observer.observe(body);

    return () => {
      body.removeEventListener("scroll", update);
      observer.disconnect();
    };
  }, [rows.length]);

  const flatRows = useMemo(() => {
    const items: Array<
      | { key: string; type: "interface"; height: number; group: (typeof groupedByInterface)[number] }
      | {
          key: string;
          type: "scope";
          height: number;
          group: TimelineScopeGroup;
          expanded: boolean;
          onToggle: () => void;
        }
      | {
          key: string;
          type: "proto";
          height: number;
          group: TimelineProtoGroup;
          expanded: boolean;
          onToggle: () => void;
        }
      | {
          key: string;
          type: "stream" | "flow";
          height: number;
          row: TimelineRow;
          rowKey: string;
          childCount?: number;
          expanded?: boolean;
          onToggle?: () => void;
        }
    > = [];

    for (const group of groupedByInterface) {
      items.push({
        key: `if:${group.key}`,
        type: "interface",
        height: 32,
        group
      });

      if (!(interfaceExpanded[group.key] ?? expandLevel !== "interface")) continue;
      const scopeGroups = buildTimelineScopeGroups(group.rows, group.key, range.end);

      for (const scopeGroup of scopeGroups) {
        const scopeIsExpanded = scopeExpanded[scopeGroup.key] ?? expandLevel !== "interface";
        items.push({
          key: `scope:${scopeGroup.key}`,
          type: "scope",
          height: 32,
          group: scopeGroup,
          expanded: scopeIsExpanded,
          onToggle: () => setScopeExpanded((current) => ({ ...current, [scopeGroup.key]: !scopeIsExpanded }))
        });
        if (!scopeIsExpanded) continue;
        const protoGroups = buildTimelineProtoGroups(scopeGroup.rows, scopeGroup.key, range.end);

        for (const protoGroup of protoGroups) {
          const groupExpanded = protoExpanded[protoGroup.key] ?? (expandLevel === "stream" || expandLevel === "flow");
        items.push({
          key: `proto:${protoGroup.key}`,
          type: "proto",
          height: 32,
          group: protoGroup,
          expanded: groupExpanded,
          onToggle: () => setProtoExpanded((current) => ({ ...current, [protoGroup.key]: !groupExpanded }))
        });

          if (!groupExpanded) continue;
          for (const { stream, flows } of protoGroup.rows) {
          const isExpanded = expanded[stream.streamKey] ?? expandLevel === "flow";
          items.push({
            key: `stream:${stream.streamKey}`,
            type: "stream",
            height: 32,
            row: stream,
            rowKey: stream.streamKey,
            childCount: flows.length,
            expanded: isExpanded,
            onToggle:
              flows.length > 0
                ? () => setExpanded((current) => ({ ...current, [stream.streamKey]: !isExpanded }))
                : undefined
          });

            if (!isExpanded) continue;
            for (const flow of flows) {
            const flowKey = `${stream.streamKey}::${flow.flowKey ?? flow.streamKey}`;
              items.push({
              key: `flow:${flowKey}`,
              type: "flow",
              height: 32,
              row: flow,
              rowKey: flowKey
              });
            }
          }
        }
      }
    }
    return items;
  }, [groupedByInterface, interfaceExpanded, scopeExpanded, expanded, protoExpanded, range.end, expandLevel]);

  useEffect(() => {
