      consumed += item.height;
      if (item.type === "interface") labels.splice(0, labels.length, item.group.label);
      else if (item.type === "scope") labels.splice(1, labels.length - 1, item.group.label);
      else if (item.type === "proto") labels.splice(2, labels.length - 2, item.group.proto);
      else if (item.type === "stream") labels.splice(3, labels.length - 3, timelineRowLabel(item.row));
    }
    return labels.length > 1 ? labels : [];
  }, [flatRows, viewport.top]);

  if (groupedByInterface.length === 0) {
    return (
      <div className="timeline-placeholder">
        <strong>Timeline is empty</strong>
        <span>No stream lifetime data matches the current filter yet.</span>
      </div>
    );
  }

  return (
      <div
        ref={chartRef}
        className="timeline-chart"
        onClick={(event) => {
          const target = event.target as HTMLElement;
          if (!target.closest(".timeline-axis-scale, .timeline-row-track")) return;
          const selected = timeFromClientX(event.clientX);
          if (selected !== null) onSelectTime?.(selected);
        }}
        onPointerMove={(event) => {
          setIsHoveringCursor(true);
          pendingCursorXRef.current = event.clientX;
          if (cursorRafRef.current !== null) return;
          cursorRafRef.current = window.requestAnimationFrame(() => {
            cursorRafRef.current = null;
            const x = pendingCursorXRef.current;
            if (x !== null) updateCursor(x);
          });
        }}
        onPointerLeave={() => {
          setIsHoveringCursor(false);
          setCursorSec(Math.min(range.end, Math.max(range.start, nowSec)));
        }}
      >
      <div className="timeline-axis">
        <div className="timeline-axis-label">
          {stickyContext.length > 0 ? (
            <div className="timeline-sticky-context" aria-label="Current timeline hierarchy" title={stickyContext.join(" › ")}>
              {stickyContext.join(" › ")}
            </div>
          ) : null}
        </div>
        <div className="timeline-axis-scale" ref={axisScaleRef}>
          <div className="timeline-cursor-label" style={{ left: `${clampPercent(cursorPercent)}%` }} title={cursorLabel}>
            {cursorLabel}
          </div>
          {range.ticks.map((tick) => (
            <div key={tick} className="timeline-axis-tick" style={{ left: `${percent(tick, range.start, range.end)}%` }}>
              <span>{formatTick(tick, range.end - range.start)}</span>
            </div>
          ))}
        </div>
      </div>
      <div className="timeline-rows">
        {virtualized.topPad > 0 ? <div style={{ height: virtualized.topPad }} /> : null}
        {virtualized.visible.map((item) => {
          if (item.type === "interface") {
            return (
              <div key={item.key} className="timeline-virtual-item" style={{ height: item.height }}>
                <TimelineInterfaceLane
                  group={item.group}
                  range={range}
                  cursorPercent={clampPercent(cursorPercent)}
                  cursorSec={cursorSec}
                  expanded={interfaceExpanded[item.group.key] ?? true}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={() => setInterfaceExpanded((current) => ({ ...current, [item.group.key]: !(current[item.group.key] ?? true) }))}
                />
              </div>
            );
          }

          if (item.type === "proto") {
            return (
              <div key={item.key} className="timeline-virtual-item" style={{ height: item.height }}>
                <TimelineProtoLane
                  group={item.group}
                  range={range}
                  cursorPercent={clampPercent(cursorPercent)}
                  cursorSec={cursorSec}
                  expanded={item.expanded}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={item.onToggle}
                />
              </div>
            );
          }

          if (item.type === "scope") {
            return (
              <div key={item.key} className="timeline-virtual-item" style={{ height: item.height }}>
                <TimelineScopeLane
                  group={item.group}
                  range={range}
                  cursorPercent={clampPercent(cursorPercent)}
                  cursorSec={cursorSec}
                  expanded={item.expanded}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={item.onToggle}
                />
              </div>
            );
          }

          return (
            <div key={item.key} className="timeline-virtual-item" style={{ height: item.height }}>
              <TimelineLane
                rowKey={item.rowKey}
                row={item.row}
                range={range}
                cursorPercent={clampPercent(cursorPercent)}
                cursorSec={cursorSec}
                fadeSec={fadeSec}
                isHovered={hoveredRowKey === item.rowKey}
                onHoverChange={setHoveredRowKey}
                childCount={item.childCount ?? 0}
                expanded={item.expanded ?? false}
                onToggle={item.onToggle}
              />
            </div>
          );
        })}
        {virtualized.bottomPad > 0 ? <div style={{ height: virtualized.bottomPad }} /> : null}
      </div>
    </div>
  );
}

function TimelineScopeLane({
  group,
  range,
  cursorPercent,
  cursorSec,
  expanded,
  isHovered,
  onHoverChange,
  onToggle
}: {
  group: TimelineScopeGroup;
  range: { start: number; end: number };
  cursorPercent: number;
  cursorSec: number;
  expanded: boolean;
  isHovered: boolean;
  onHoverChange: (key: string | null) => void;
  onToggle: () => void;
}) {
  const focused = group.segments.some((segment) => cursorSec >= segment.start && cursorSec <= segment.end);
  const focusClass = focused ? " timeline-row-cursor-focused" : isHovered ? " timeline-row-hovered" : "";
  return (
    <div className={`timeline-scope-row${focusClass}`} onPointerEnter={() => onHoverChange(group.key)} onPointerLeave={() => onHoverChange(null)}>
      <div className="timeline-scope-label" title={group.key}>
