function TimelineScopeLane({
  group,
  range,
  cursorPercent,
  cursorSec,
  expanded,
  isHovered,
  onHoverChange,
  onToggle
}: {
  group: TimelineScopeGroup;
  range: { start: number; end: number };
  cursorPercent: number;
  cursorSec: number;
  expanded: boolean;
  isHovered: boolean;
  onHoverChange: (key: string | null) => void;
  onToggle: () => void;
}) {
  const focused = group.segments.some((segment) => cursorSec >= segment.start && cursorSec <= segment.end);
  const focusClass = focused ? " timeline-row-cursor-focused" : isHovered ? " timeline-row-hovered" : "";
  return (
    <div className={`timeline-scope-row${focusClass}`} onPointerEnter={() => onHoverChange(group.key)} onPointerLeave={() => onHoverChange(null)}>
      <div className="timeline-scope-label" title={group.key}>
        <strong>
          <button type="button" className="timeline-toggle" onClick={(event) => { event.stopPropagation(); onToggle(); }} aria-label={expanded ? "Collapse scope rows" : "Expand scope rows"}>
            <Icon name="expand" size={15} className={expanded ? "is-expanded" : ""} />
          </button>
          <span className="timeline-label-text">{group.label}</span>
          <TimelineCountBadge count={group.rows.length} />
        </strong>
      </div>
      <div className="timeline-row-track timeline-scope-track">
        <div className="timeline-cursor-line" style={{ left: `${cursorPercent}%` }} aria-hidden="true" />
        {group.segments.map((segment, index) => {
          const start = percent(segment.start, range.start, range.end);
          const end = percent(segment.end, range.start, range.end);
          return <div key={`${group.key}:${index}:${segment.start}`} className={`timeline-segment timeline-segment-scope${group.active && index === group.segments.length - 1 && segment.end >= range.end ? " active" : ""}`} style={{ left: `${start}%`, width: `${Math.max(0.6, end - start)}%` }} />;
        })}
      </div>
    </div>
  );
}

