  const baseClass = row.rowType === "flow" ? "timeline-segment-flow" : row.rowType === "stream" ? "timeline-segment-stream" : "timeline-segment-interface";
  const key = `${row.flowKey ?? row.streamKey}:${index}:${segment.start}`;

  if (segment.end === null) {
