        style={{
          left: `${start}%`,
          width: `${width}%`
        }}
      />
    );
  }

  const fadeStart = Math.max(segment.start, fullEnd - fadeSec);
  if (fadeStart <= segment.start + 1e-6) {
    return (
      <div
        key={key}
        className={`timeline-segment ${baseClass} timeline-segment-fade active`}
        style={{
          left: `${start}%`,
          width: `${width}%`
        }}
      />
    );
  }

  const solidEnd = percent(fadeStart, range.start, range.end);
  const fadeBegin = percent(fadeStart, range.start, range.end);
  const fadeWidth = Math.max(0.6, end - fadeBegin);

  return (
