function renderSegment(row: TimelineRow, segment: { start: number; end: number | null }, index: number, range: { start: number; end: number }, fadeSec: number) {
  const fullEnd = segment.end ?? range.end;
  const start = percent(segment.start, range.start, range.end);
  const end = percent(fullEnd, range.start, range.end);
  const width = Math.max(0.6, end - start);
  const baseClass = row.rowType === "flow" ? "timeline-segment-flow" : row.rowType === "stream" ? "timeline-segment-stream" : "timeline-segment-interface";
  const key = `${row.flowKey ?? row.streamKey}:${index}:${segment.start}`;

  if (segment.end === null) {
    return (
      <div
        key={key}
        className={`timeline-segment ${baseClass} active`}
        style={{
          left: `${start}%`,
          width: `${width}%`
        }}
      />
    );
  }

  const fadeStart = Math.max(segment.start, fullEnd - fadeSec);
  if (fadeStart <= segment.start + 1e-6) {
    return (
      <div
        key={key}
        className={`timeline-segment ${baseClass} timeline-segment-fade active`}
        style={{
          left: `${start}%`,
          width: `${width}%`
        }}
      />
    );
  }

  const solidEnd = percent(fadeStart, range.start, range.end);
  const fadeBegin = percent(fadeStart, range.start, range.end);
  const fadeWidth = Math.max(0.6, end - fadeBegin);

  return (
    <Fragment key={key}>
      <div
        key={`${key}:solid`}
        className={`timeline-segment ${baseClass} timeline-segment-split-solid active`}
        style={{
          left: `${start}%`,
          width: `${Math.max(0.6, solidEnd - start)}%`
        }}
      />
      <div
        key={`${key}:fade`}
        className={`timeline-segment ${baseClass} timeline-segment-fade timeline-segment-split-fade active`}
        style={{
          left: `${fadeBegin}%`,
          width: `${fadeWidth}%`
        }}
      />
    </Fragment>
  );
}

function percent(value: number, start: number, end: number) {
  return ((value - start) / Math.max(1e-6, end - start)) * 100;
}

function clampPercent(value: number) {
  return Math.min(99.5, Math.max(0.5, value));
}

function formatTick(value: number, spanSec: number) {
  return new Date(value * 1000).toLocaleTimeString([], {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: spanSec <= 600 ? "2-digit" : undefined
  });
}

function formatCursor(value: number) {
  return new Date(value * 1000).toLocaleString([], {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  });
}

