function buildTimelineScopeGroups(rows: TimelineStreamGroup[], interfaceKey: string, rangeEndSec: number): TimelineScopeGroup[] {
  const groups = new Map<string, TimelineStreamGroup[]>();
  for (const item of rows) {
    const key = timelineScopeKey(item.stream.scope);
    const bucket = groups.get(key) ?? [];
    bucket.push(item);
    groups.set(key, bucket);
  }
  return [...groups.entries()]
    .map(([scopeKey, grouped]) => ({
      key: `${interfaceKey}::${scopeKey}`,
      label: timelineScopeLabel(grouped[0]?.stream.scope),
      rows: grouped,
      segments: mergeSegments(grouped.flatMap(({ stream }) => stream.segments.map((segment) => ({ start: segment.start, end: segment.end ?? rangeEndSec })))),
      active: grouped.some(({ stream }) => stream.active)
    }))
    .sort((a, b) => a.label.localeCompare(b.label));
}

function timelineScopeKey(scope: NetworkScope | undefined) {
  if (!scope?.known) return "unknown";
  if (scope.layers.length === 0) return "untagged";
  return scope.layers.map((layer) => layer.kind === "vlan"
    ? `vlan:${layer.id ?? "unknown"}:${layer.priority ?? ""}:${layer.dei ?? ""}`
    : `vxlan:${layer.vni ?? "unknown"}`).join("|");
}

function timelineScopeLabel(scope: NetworkScope | undefined) {
  if (!scope?.known) return "Scope unknown";
  if (scope.layers.length === 0) return "Untagged";
  return scope.layers.map((layer) => layer.kind === "vlan"
    ? `VLAN ${layer.id ?? "unknown"}`
    : `VNI ${layer.vni ?? "unknown"}`).join(" / ");
}

function buildTimelineProtoGroups(
  rows: TimelineStreamGroup[],
  scopeKey: string,
  rangeEndSec: number
) {
  const groups = new Map<string, Array<{ stream: TimelineRow; flows: TimelineRow[] }>>();
  for (const item of rows) {
    const proto = item.stream.proto || item.stream.kind || "OTHER";
    const bucket = groups.get(proto) ?? [];
    bucket.push(item);
    groups.set(proto, bucket);
