  min-height: 100%;
  display: grid;
  place-items: center;
  padding: 18px;
  text-align: center;
}
.timeline-placeholder strong {
  display: block;
  color: #e9f2fa;
  margin-bottom: 6px;
}
.timeline-placeholder span {
  display: block;
  color: var(--muted);
  font-size: 12px;
  max-width: 28ch;
}
.timeline-chart {
  min-height: 100%;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 10px;
}
.timeline-axis {
  display: grid;
  grid-template-columns: minmax(148px, 220px) minmax(0, 1fr);
  gap: 14px;
  align-items: end;
  position: sticky;
  top: 0;
  z-index: 4;
  padding: 0 0 6px;
/*  background:
    linear-gradient(180deg, rgba(5,10,18,.96), rgba(5,10,18,.88));*/
}
.timeline-axis-scale {
  position: relative;
  height: 24px;
}
.timeline-cursor-label {
  position: absolute;
/*  top: -1px;*/
  top: 20px;
  transform: translateX(-50%);
  padding: 2px 6px;
/*  border-radius: 999px;*/
  border-radius: 2px;
  border: 1px solid rgba(102,217,239,.32);
  background: rgba(8,14,22,.86);
  color: #dff8ff;
/*  font-size: 10px;*/
  font-size: 16px;
  line-height: 1.1;
  white-space: nowrap;
  pointer-events: none;
  z-index: 3;
  box-shadow: 0 6px 16px rgba(0,0,0,.24);
}
.timeline-axis-tick {
  position: absolute;
.timeline-toggle-spacer {
  flex: 0 0 22px;
  width: 22px;
  height: 22px;
  display: inline-grid;
  place-items: center;
}
.timeline-toggle {
  border: 1px solid rgba(143,164,188,.18);
/*  border-radius: 5px;*/
  border-radius: 2px;
  background: rgba(255,255,255,.03);
/*  color: #d7e3ee;*/
  color: var(--muted);
  padding: 0;
  cursor: pointer;
}
.timeline-toggle:hover {
  background: rgba(255,255,255,.06);
  border-color: rgba(143,164,188,.28);
  color: #e9f2fa;
}
.timeline-row-track {
  position: relative;
/*  min-height: 22px;*/
  min-height: 24px;
  border-radius: 4px;
  background:
    linear-gradient(90deg, rgba(124,135,152,.08) 1px, transparent 1px) 0 0 / 64px 100%,
    rgba(5,10,18,.24);
  overflow: hidden;
}
.timeline-cursor-line {
  position: absolute;
  top: 0;
  bottom: 0;
/*  width: 2px;*/
  width: 1px;
  transform: translateX(-1px);
/*  background: rgba(102,217,239,.96);*/
/*  box-shadow: 0 0 0 1px rgba(102,217,239,.18), 0 0 10px rgba(102,217,239,.12);*/
  background: rgba(255,255,255,.56);
  box-shadow: 0 0 0 1px rgba(255,255,255,.18), 0 0 10px rgba(255,255,255,.12);
  pointer-events: none;
  z-index: 2;
}
.timeline-segment {
  position: absolute;
  top: 4px;
  bottom: 4px;
/*  border-radius: 2px;*/

.timeline-interface-header.timeline-row-cursor-focused::before,
.timeline-interface-header.timeline-row-cursor-focused::after,
.timeline-proto-row.timeline-row-cursor-focused::before,
.timeline-proto-row.timeline-row-cursor-focused::after,
.timeline-row.timeline-row-cursor-focused::before,
.timeline-row.timeline-row-cursor-focused::after {
  content: none;
}

.timeline-toggle svg {
  transition: transform .16s ease;
}

.timeline-toggle svg.is-expanded {
  transform: rotate(90deg);
}


/* Scope adds the VLAN/VXLAN observation boundary between NIC and protocol. */
.timeline-scope-row,
.timeline-interface-header,
.timeline-proto-row,
.timeline-row {
  display: grid;
  grid-template-columns: var(--timeline-label-width) minmax(0, 1fr);
  gap: var(--space-2);
  align-items: center;
  min-height: 32px;
  height: 32px;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 75%, transparent);
  border-radius: 0;
  box-shadow: none;
}

.timeline-scope-label,
.timeline-interface-label,
.timeline-proto-label,
.timeline-row-label {
  min-width: 0;
  align-self: stretch;
  display: grid;
  align-content: center;
  padding: 0 var(--space-2);
  border-right: 1px solid color-mix(in srgb, var(--line) 74%, transparent);
  background: color-mix(in srgb, var(--surface-muted) 88%, var(--surface));
}

.timeline-scope-label {
  padding-left: calc(var(--space-2) + 28px);
}

.timeline-proto-label {
  padding-left: calc(var(--space-2) + 56px);
}

.timeline-row-stream .timeline-row-label {
  padding-left: calc(var(--space-2) + 84px);
}

.timeline-row-flow .timeline-row-label {
  padding-left: calc(var(--space-2) + 112px);
}

.timeline-scope-label strong,
.timeline-interface-label strong,
.timeline-proto-label strong,
.timeline-row-label strong {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 5px;
  color: var(--text-strong);
  font-size: var(--font-size-sm);
  font-weight: 600;
  line-height: 1.2;
}

.timeline-scope-label .timeline-label-text,
.timeline-interface-label .timeline-label-text,
.timeline-proto-label .timeline-label-text,
.timeline-row-label .timeline-label-text {
  color: var(--text-strong);
  font-size: var(--font-size-xs);
}

.timeline-row-stream .timeline-row-label strong,
.timeline-row-flow .timeline-row-label strong {
  font-weight: 400;
}

.timeline-scope-label strong em,
.timeline-interface-label strong em,
.timeline-proto-label strong em,
.timeline-row-label strong em {
  flex: 0 0 auto;
  color: var(--muted);
  font-size: inherit;
  font-style: normal;
  font-weight: inherit;
}

.timeline-scope-label strong em::before,
.timeline-interface-label strong em::before,
.timeline-proto-label strong em::before,
.timeline-row-label strong em::before {
  content: "(";
}

.timeline-scope-label strong em::after,
.timeline-interface-label strong em::after,
.timeline-proto-label strong em::after,
.timeline-row-label strong em::after {
  content: ")";
}

.timeline-scope-track,
.timeline-interface-track,
.timeline-proto-track,
.timeline-row-track {
  position: relative;
  z-index: 1;
  height: 100%;
  min-height: 0;
  margin-left: 0;
  background: transparent;
}

.timeline-segment.active.timeline-segment-scope {
  background: color-mix(in srgb, var(--muted) 62%, transparent);
}

.timeline-scope-row:hover,
.timeline-scope-row.timeline-row-hovered,
.timeline-scope-row.timeline-row-cursor-focused,
.timeline-interface-header.timeline-row-hovered,
.timeline-proto-row.timeline-row-hovered,
.timeline-row.timeline-row-hovered,
.timeline-interface-header.timeline-row-cursor-focused,
.timeline-proto-row.timeline-row-cursor-focused,
.timeline-row.timeline-row-cursor-focused {
  background: var(--surface-muted);
}

.timeline-scope-row.timeline-row-hovered .timeline-scope-label,
.timeline-scope-row.timeline-row-cursor-focused .timeline-scope-label,
.timeline-interface-header.timeline-row-hovered .timeline-interface-label,
.timeline-interface-header.timeline-row-cursor-focused .timeline-interface-label,
.timeline-proto-row.timeline-row-hovered .timeline-proto-label,
.timeline-proto-row.timeline-row-cursor-focused .timeline-proto-label,
.timeline-row.timeline-row-hovered .timeline-row-label,
.timeline-row.timeline-row-cursor-focused .timeline-row-label {
  background: var(--surface-muted);
}

/* The context occupies the axis label column, leaving the time scale unobscured. */
.timeline-sticky-context {
  min-width: 0;
  overflow: hidden;
  color: var(--text-strong);
  font-size: var(--font-size-xs);
  for (let index = 1; index < sorted.length; index += 1) {
    const current = sorted[index];
    const last = merged[merged.length - 1];
    if (current.start <= last.end) {
      last.end = Math.max(last.end, current.end);
    } else {
      merged.push({ ...current });
    }
  }
  return merged;
}

function mergeSegmentsNullable(segments: Array<{ start: number; end: number | null }>) {
  if (segments.length === 0) return [];
  const normalized = segments.map((segment) => ({
    start: segment.start,
    end: segment.end ?? Number.POSITIVE_INFINITY
  }));
  const merged = mergeSegments(normalized);
  return merged.map((segment) => ({
    start: segment.start,
    end: Number.isFinite(segment.end) ? segment.end : null
  }));
}

function buildTimelineScopeGroups(rows: TimelineStreamGroup[], interfaceKey: string, rangeEndSec: number): TimelineScopeGroup[] {
  const groups = new Map<string, TimelineStreamGroup[]>();
  for (const item of rows) {
    const key = timelineScopeKey(item.stream.scope);
    const bucket = groups.get(key) ?? [];
    bucket.push(item);
    groups.set(key, bucket);
  }
  return [...groups.entries()]
    .map(([scopeKey, grouped]) => ({
      key: `${interfaceKey}::${scopeKey}`,
      label: timelineScopeLabel(grouped[0]?.stream.scope),
      rows: grouped,
      segments: mergeSegments(grouped.flatMap(({ stream }) => stream.segments.map((segment) => ({ start: segment.start, end: segment.end ?? rangeEndSec })))),
      active: grouped.some(({ stream }) => stream.active)
    }))
    .sort((a, b) => a.label.localeCompare(b.label));
}

function timelineScopeKey(scope: NetworkScope | undefined) {
  if (!scope?.known) return "unknown";
  if (scope.layers.length === 0) return "untagged";
  return scope.layers.map((layer) => layer.kind === "vlan"
    ? `vlan:${layer.id ?? "unknown"}:${layer.priority ?? ""}:${layer.dei ?? ""}`
    : `vxlan:${layer.vni ?? "unknown"}`).join("|");
}

function timelineScopeLabel(scope: NetworkScope | undefined) {
  if (!scope?.known) return "Scope unknown";
  if (scope.layers.length === 0) return "Untagged";
  return scope.layers.map((layer) => layer.kind === "vlan"
    ? `VLAN ${layer.id ?? "unknown"}`
    : `VNI ${layer.vni ?? "unknown"}`).join(" / ");
}

function buildTimelineProtoGroups(
  rows: TimelineStreamGroup[],
  scopeKey: string,
  rangeEndSec: number
) {
  const groups = new Map<string, Array<{ stream: TimelineRow; flows: TimelineRow[] }>>();
  for (const item of rows) {
    const proto = item.stream.proto || item.stream.kind || "OTHER";
    const bucket = groups.get(proto) ?? [];
    bucket.push(item);
    groups.set(proto, bucket);
  }

  return [...groups.entries()]
    .map(([proto, grouped]) => ({
      key: `${scopeKey}::${proto}`,
      proto,
      rows: grouped.sort((a, b) => b.stream.lastSeen - a.stream.lastSeen),
      segments: mergeSegments(
        grouped.flatMap(({ stream }) => stream.segments.map((segment) => ({ start: segment.start, end: segment.end ?? rangeEndSec })))
      ),
      active: grouped.some(({ stream }) => stream.active)
    }))
    .sort((a, b) => a.proto.localeCompare(b.proto));
}

