+  return <>{gaps.map((gap) => {
+    const from = Math.max(range.start, gap.from);
+    const to = Math.min(range.end, gap.to);
+    if (to <= from) return null;
+    return <div key={`${gap.reason}:${from}:${to}`} className="timeline-gap-band" style={{ left: `${percent(from, range.start, range.end)}%`, width: `${Math.max(0.4, percent(to, range.start, range.end) - percent(from, range.start, range.end))}%` }} title="Monitoring data unavailable" aria-label={label ? "Monitoring data unavailable" : undefined} />;
