import { existsSync, statSync } from "node:fs";
import fastify, { type FastifyInstance } from "fastify";
import fastifyStatic from "@fastify/static";
import { config, ensureLogFilesExist } from "./config";
import { RotatingNdjsonTail } from "./ingest/rotatingNdjsonTail";
import { TailFile } from "./ingest/tailFile";
import { normalizeMetricSampleLine, normalizeStreamsLine, normalizeTimelineLine, normalizeTopologyLine, type NormalizedInterfaceInput, type NormalizedMetricInput } from "./normalizer";
import { applyProjectedLifecycleEvent, loadProjectedStreamState, materializeProjectedStreamStates, type JsonRecord } from "./history/stream_state_query";
import { queryProjectedTopologyAt } from "./history/topology_state_query";
import { queryEventsHistory } from "./history/events_query";
import { normalizeEventLine } from "./events";
import { registerRoutes } from "./api/routes";
import { StreamStore } from "./state/store";
import { SocketServer } from "./ws/socketServer";
import { MaintenanceSettings } from "./maintenanceSettings";
import { AlertsSettings } from "./alertsSettings";
import { ProtocolMapSettings } from "./protocolMapSettings";

type RunningTail = { start(): void; stop(): void };

async function main() {
  ensureLogFilesExist();
  diagnostic(`startup source=projected cwd=${process.cwd()} root=${config.rootDir} logDir=${config.logDir} port=${config.port}`);
  diagnosticInputs();

  const app = fastify({ logger: config.httpAccessLog });
  const alertsSettings = config.stmConfigFile ? new AlertsSettings(config.stmConfigFile) : undefined;
  const protocolMapSettings = config.stmConfigFile ? new ProtocolMapSettings(config.stmConfigFile) : undefined;
  const maintenanceSettings = await MaintenanceSettings.load({
    definitionFile: config.maintenanceSettingsFile,
    runtimeFile: config.runtimeSettingsFile,
    defaults: { lostRetentionSec: config.lostRetentionSec, historyWindowSec: config.historyWindowSec, staleAfterSec: config.staleAfterSec, diagnosticLog: config.diagnosticLog }
  });
  Object.assign(config, maintenanceSettings.get().values);
  const store = new StreamStore(config.historyWindowSec, config.timelineWindowSec, config.staleAfterSec, config.lostRetentionSec, config.maxEvents, config.maxTimelineRows);
  const now = Date.now() / 1000;
  const initialEvents = await queryEventsHistory({ from: now - 24 * 3600, to: now, limit: config.maxEvents });
  for (const event of initialEvents.reverse()) store.addEvent(event);

  const initialTopology = await queryProjectedTopologyAt({ checkpointDir: config.topologyCheckpointDir, updatesDir: config.topologyUpdatesDir, time: now });
  if (initialTopology) store.applyTopologySnapshot(initialTopology);
  diagnostic(`initial state events=${store.listEvents({ limit: config.maxEvents }).length} topology=${initialTopology ? "loaded" : "missing"}`);

  const sockets = new SocketServer(app.server, store, config.streamsPatchIntervalMs, config.wsMaxBufferedBytes);
  await registerRoutes(app, store, maintenanceSettings, alertsSettings, protocolMapSettings, (values) => {
    Object.assign(config, values);
    store.updateRuntimeConfig(values);
    sockets.broadcastConfig(values);
  });
  if (existsSync(config.clientDist)) {
    await app.register(fastifyStatic, { root: config.clientDist, prefix: "/" });
    app.setNotFoundHandler((request, reply) => {
      if (request.raw.url?.startsWith("/api") || request.raw.url === "/ws") return reply.code(404).send({ error: "not found" });
      return reply.sendFile("index.html");
    });
  }

  sockets.start();
  const { tails, flushMetrics } = await createProjectedTails(app, store);
  tails.forEach((tail) => tail.start());
  const close = async () => { flushMetrics(); tails.forEach((tail) => tail.stop()); await app.close(); };
  process.on("SIGINT", () => void close());
  process.on("SIGTERM", () => void close());
  await app.listen({ host: config.host, port: config.port });
}

async function createProjectedTails(app: FastifyInstance, store: StreamStore): Promise<{ tails: RunningTail[]; flushMetrics: () => void }> {
  const state = await loadProjectedStreamState(config.streamStateDir, Number.POSITIVE_INFINITY);
  const applyStreams = (time: number) => store.applyStreamSnapshot(materializeProjectedStreamStates(state.streams, time), time);
  if (state.hasRecords) applyStreams(Date.now() / 1000);

  const streams = new RotatingNdjsonTail({ root: `${config.streamStateDir}/delta`, extension: ".ndjson", pollMs: config.pollMs, startAtLatestFile: true,
    recordId: sourceRecordId,
    initialSkipRecordIds: state.latestDeltaRecordIds,
    onLine: (line) => { try { const delta = parseRecord(line); const time = Number(delta?.time ?? 0); if (!delta || !Number.isFinite(time) || time < state.checkpointTime) return; applyProjectedLifecycleEvent(state.streams, delta.event); applyStreams(time); } catch (error) { app.log.warn({ error }, "failed to parse projected stream delta"); } },
import { promises as fs } from "node:fs";
import path from "node:path";

const READ_CHUNK_BYTES = 1024 * 1024;

export type RotatingNdjsonTailOptions = {
  root: string;
  extension: ".ndjson" | ".jsonl";
  pollMs: number;
  onLine: (line: string, file: string) => void;
  onError?: (error: unknown) => void;
  maxRecentRecordIds?: number;
  startAtLatestFile?: boolean;
  recordId?: (line: string) => string | undefined;
  /** Records already included in a startup snapshot. They are skipped when replaying the initial file. */
  initialSkipRecordIds?: ReadonlySet<string>;
};

/** Tails lexically ordered hourly and part-suffixed JSONL files without consuming a partial final line. */
export class RotatingNdjsonTail {
  private cursorPath?: string;
  private cursorOffset = 0;
  private timer?: NodeJS.Timeout;
  private reading = false;
  private readonly recentRecordIds = new Set<string>();
  private readonly recentRecordOrder: string[] = [];
  private readonly initialSkipRecordIds?: ReadonlySet<string>;

  constructor(private readonly options: RotatingNdjsonTailOptions) {
    this.initialSkipRecordIds = options.initialSkipRecordIds;
  }

  start() {
    this.timer = setInterval(() => void this.tick(), this.options.pollMs);
    void this.tick();
  }

  stop() {
    if (this.timer) clearInterval(this.timer);
  }

  private async tick() {
    if (this.reading) return;
    this.reading = true;
    try {
      const files = await this.listFiles();
      if (files.length === 0) return;

      let index = this.cursorPath ? files.indexOf(this.cursorPath) : (this.options.startAtLatestFile ? files.length - 1 : 0);
      if (index < 0) index = files.findIndex((file) => !this.cursorPath || file > this.cursorPath);
      if (index < 0) return;

      for (; index < files.length; index += 1) {
        const file = files[index];
        if (file !== this.cursorPath) {
          this.cursorPath = file;
          this.cursorOffset = 0;
        }
        const hasPartialLine = await this.readAvailable(file);
        if (hasPartialLine || index === files.length - 1) break;
      }
    } catch (error) {
      this.options.onError?.(error);
    } finally {
      this.reading = false;
    }
  }

  private async listFiles() {
    const files: string[] = [];
    const walk = async (directory: string): Promise<void> => {
      let entries;
      try {
        entries = await fs.readdir(directory, { withFileTypes: true });
      } catch (error: any) {
        if (error?.code === "ENOENT") return;
        throw error;
      }
      for (const entry of entries) {
        const candidate = path.join(directory, entry.name);
        if (entry.isDirectory()) await walk(candidate);
        else if (entry.isFile() && entry.name.endsWith(this.options.extension)) files.push(candidate);
      }
    };
    await walk(this.options.root);
    return files.sort();
  }

  private async readAvailable(file: string) {
    const stat = await fs.stat(file);
    if (stat.size < this.cursorOffset) this.cursorOffset = 0;
    if (stat.size === this.cursorOffset) return false;

    const handle = await fs.open(file, "r");
    try {
      let position = this.cursorOffset;
      let pending = Buffer.alloc(0);
      while (position < stat.size) {
        const length = Math.min(READ_CHUNK_BYTES, stat.size - position);
        const chunk = Buffer.allocUnsafe(length);
        const { bytesRead } = await handle.read(chunk, 0, length, position);
        if (bytesRead <= 0) break;
        position += bytesRead;
        pending = Buffer.concat([pending, chunk.subarray(0, bytesRead)]);

        let newline = pending.indexOf(0x0a);
        while (newline >= 0) {
          const line = pending.subarray(0, newline).toString("utf8").replace(/\r$/, "").trim();
          this.cursorOffset += newline + 1;
          pending = pending.subarray(newline + 1);
          if (line) this.consumeLine(line, file);
          newline = pending.indexOf(0x0a);
        }
      }
      return pending.length > 0;
    } finally {
      await handle.close();
    }
  }

  private consumeLine(line: string, file: string) {
    const recordId = this.options.recordId?.(line) ?? extractRecordId(line);
    if (recordId) {
      if (this.initialSkipRecordIds?.has(recordId)) return;
      if (this.recentRecordIds.has(recordId)) return;
      this.recentRecordIds.add(recordId);
      this.recentRecordOrder.push(recordId);
      const limit = this.options.maxRecentRecordIds ?? 10_000;
      while (this.recentRecordOrder.length > limit) {
        const oldest = this.recentRecordOrder.shift();
        if (oldest) this.recentRecordIds.delete(oldest);
      }
    }
    this.options.onLine(line, file);
  }
}

function extractRecordId(line: string) {
  try {
    const record = JSON.parse(line) as { record_id?: unknown };
    return typeof record.record_id === "string" ? record.record_id : undefined;
  } catch {
    return undefined;
  }
}
