export function deriveTimelineDataGaps(
  points: AvailabilityPoint[],
  from: number,
  to: number,
  maxIntervalSec = AVAILABILITY_MAX_INTERVAL_SEC
): TimelineDataGap[] {
  const uniquePoints = [...new Set(points
    .map((point) => point.time)
    .filter((time) => Number.isFinite(time) && time <= to))]
    .sort((a, b) => a - b);
  const gaps: TimelineDataGap[] = [];

  for (let index = 1; index < uniquePoints.length; index += 1) {
    const gapFrom = uniquePoints[index - 1] + maxIntervalSec;
    const gapTo = uniquePoints[index];
    if (gapTo <= gapFrom) continue;
    const clippedFrom = Math.max(from, gapFrom);
    const clippedTo = Math.min(to, gapTo);
    if (clippedTo > clippedFrom) gaps.push({ from: clippedFrom, to: clippedTo, reason: "monitor-unavailable" });
  }

  return gaps;
}

async function readLatestAvailabilityAtOrBefore(to: number): Promise<AvailabilityPoint | undefined> {
  const files = listAvailabilityFilesBefore(to);
  for (let index = files.length - 1; index >= 0; index -= 1) {
    const points = await readAvailabilityFiles([files[index]]);
    const latest = points.reduce<AvailabilityPoint | undefined>((current, point) => {
      if (point.time > to || (current && point.time <= current.time)) return current;
      return point;
    }, undefined);
    if (latest) return latest;
  }
  return undefined;
}

async function readAvailabilityFiles(files: string[]): Promise<AvailabilityPoint[]> {
  const points: AvailabilityPoint[] = [];
  for (const file of files) {
    const input = readline.createInterface({ input: createReadStream(file), crlfDelay: Infinity });
    for await (const line of input) {
      const point = parseAvailabilityLine(line);
      if (point) points.push(point);
    }
  }
