function rangePreset(range: string) {
  switch (range) {
    case "24h":
      return { windowSec: 24 * 3600, resolutionSec: 60 };
    case "12h":
      return { windowSec: 12 * 3600, resolutionSec: 60 };
    case "6h":
      return { windowSec: 6 * 3600, resolutionSec: 60 };
    case "3h":
      return { windowSec: 3 * 3600, resolutionSec: 60 };
    case "1h":
      return { windowSec: 3600, resolutionSec: 60 };
    case "30m":
      return { windowSec: 1800, resolutionSec: 60 };
    case "10m":
      return { windowSec: 600, resolutionSec: 60 };
    case "5m":
    default:
      return { windowSec: 300 };
  }
}

function timelineRangePreset(range: string) {
  switch (range) {
    case "24h":
      return { windowSec: 24 * 3600 };
    case "12h":
      return { windowSec: 12 * 3600 };
    case "6h":
      return { windowSec: 6 * 3600 };
    case "3h":
      return { windowSec: 3 * 3600 };
    case "1h":
      return { windowSec: 3600 };
    case "30m":
      return { windowSec: 1800 };
    case "10m":
      return { windowSec: 600 };
    case "5m":
    default:
      return { windowSec: 300 };
  }
}

function clampTimelineWindow({
  desiredTo,
  windowSec,
  available,
  nowSec
}: {
  desiredTo: number;
  windowSec: number;
  available: TimelineWindow;
  nowSec: number;
}) {
  const maxAvailableTo = Math.min(available.to, nowSec);
  const safeAvailable = {
    from: Math.min(available.from, maxAvailableTo),
    to: maxAvailableTo
  };
  const availableSpan = Math.max(0, safeAvailable.to - safeAvailable.from);
  if (availableSpan <= windowSec) {
    return {
      from: safeAvailable.from,
      to: safeAvailable.to
    };
  }

  const minTo = safeAvailable.from + windowSec;
  const maxTo = safeAvailable.to;
  const safeTo = Math.min(maxTo, Math.max(minTo, desiredTo));
  return {
    from: safeTo - windowSec,
    to: safeTo
  };
}

function clipTimelineRows(rows: TimelineRow[], from: number, to: number) {
  return rows
    .map((row) => {
      const segments = row.segments
        .map((segment) => {
          const effectiveEnd = segment.end ?? to;
          if (effectiveEnd <= from || segment.start >= to) return undefined;
          return {
            start: Math.max(segment.start, from),
            end: segment.end === null ? null : Math.min(segment.end, to)
          };
        })
        .filter((segment): segment is NonNullable<typeof segment> => segment !== undefined);

