function createMetricSampleBatcher(store: StreamStore, app: FastifyInstance) {
  const interfaces: NormalizedInterfaceInput[] = [];
  const metrics: NormalizedMetricInput[] = [];
  let timer: NodeJS.Timeout | undefined;

  const flush = () => {
    if (timer) clearTimeout(timer);
    timer = undefined;
    const interfaceBatch = interfaces.splice(0, interfaces.length);
    const metricBatch = metrics.splice(0, metrics.length);
    if (interfaceBatch.length > 0) store.upsertInterfaces(interfaceBatch);
    if (metricBatch.length > 0) store.addMetrics(metricBatch);
  };

  return {
    push: (line: string) => {
      try {
        const sample = normalizeMetricSampleLine(line);
        if (!sample) return;
        if (sample.interface) interfaces.push(sample.interface);
        if (sample.metric) metrics.push(sample.metric);
        if (!timer) timer = setTimeout(flush, 50);
      } catch (error) {
        app.log.warn({ error }, "failed to parse metric sample");
      }
    },
    flush
  };
}
