 29	export function deriveTimelineDataGaps(
 30	  points: AvailabilityPoint[],
 31	  from: number,
 32	  to: number,
 33	  maxIntervalSec = AVAILABILITY_MAX_INTERVAL_SEC
 34	): TimelineDataGap[] {
 35	  const uniquePoints = [...new Set(points
 36	    .map((point) => point.time)
 37	    .filter((time) => Number.isFinite(time) && time <= to))]
 38	    .sort((a, b) => a - b);
 39	  const gaps: TimelineDataGap[] = [];
 40	
 41	  for (let index = 1; index < uniquePoints.length; index += 1) {
 42	    const gapFrom = uniquePoints[index - 1] + maxIntervalSec;
 43	    const gapTo = uniquePoints[index];
 44	    if (gapTo <= gapFrom) continue;
 45	    const clippedFrom = Math.max(from, gapFrom);
 46	    const clippedTo = Math.min(to, gapTo);
 47	    if (clippedTo > clippedFrom) gaps.push({ from: clippedFrom, to: clippedTo, reason: "monitor-unavailable" });
 48	  }
 49	
 50	  return gaps;
 51	}
