int stm_projector::run_follow() {
	for(;;) {
		if(run_once() != 0) {
			return -1;
		}
		std::this_thread::sleep_for(m_cfg.poll_interval);
	}
}

void stm_projector::load_state() {
	std::ifstream input(m_cfg.state_file);
	if(!input) {
		return;
	}
	try {
		json state;
		input >> state;
		m_event_cursor = journal_reader::cursor_from_json(state.value("event_cursor", json::object()));
		m_metrics_cursor = journal_reader::cursor_from_json(state.value("metrics_cursor", json::object()));
		if(m_stream_state) m_stream_state->import_state(state.value("stream_state", json::object()));
		if(state.contains("current_metrics") && state["current_metrics"].is_array()) m_current_metrics = state["current_metrics"].get<json::array_t>();
		if(state.contains("current_interfaces") && state["current_interfaces"].is_array()) m_current_interfaces = state["current_interfaces"].get<json::array_t>();
		if(state.contains("active_alerts") && state["active_alerts"].is_object()) m_active_alerts = state["active_alerts"];
		if(state.contains("last_event_record_id") && state["last_event_record_id"].is_string()) m_last_event_record_id = state["last_event_record_id"];
		if(state.contains("last_metrics_record_id") && state["last_metrics_record_id"].is_string()) m_last_metrics_record_id = state["last_metrics_record_id"];
		if(m_topology_state) m_topology_state->import_state(state.value("topology_state", json::object()));
	}
	catch(const std::exception &e) {
		trace(1, "projector: state load failed: %s", e.what());
	}
}

void stm_projector::save_state() const {
	if(!m_cfg.state_file.parent_path().empty()) {
		std::filesystem::create_directories(m_cfg.state_file.parent_path());
	}
	const auto temporary = m_cfg.state_file.string() + ".tmp";
	std::ofstream output(temporary, std::ios::trunc);
	if(!output) {
		trace(1, "projector: state write failed: %s", temporary.c_str());
		return;
	}
	output << json{
		{"schema_version", 1},
		{"event_cursor", journal_reader::cursor_json(m_event_cursor)},
		{"metrics_cursor", journal_reader::cursor_json(m_metrics_cursor)},
		{"stream_state", m_stream_state ? m_stream_state->export_state() : json::object()},
		{"current_metrics", m_current_metrics},
		{"current_interfaces", m_current_interfaces},
		{"active_alerts", m_active_alerts},
		{"last_event_record_id", m_last_event_record_id},
		{"last_metrics_record_id", m_last_metrics_record_id},
		{"topology_state", m_topology_state ? m_topology_state->export_state() : json::object()},
	}.dump() << '\n';
	output.flush();
	std::error_code ec{};
	std::filesystem::rename(temporary, m_cfg.state_file, ec);
	if(ec) {
		std::filesystem::remove(m_cfg.state_file, ec);
		ec.clear();
		std::filesystem::rename(temporary, m_cfg.state_file, ec);
	}
}

int stm_projector::project_event(const json &record) {
	event_record event;
	if(!as_event_record(record, event)) {
		return 0;
	}
	const int rc = m_timeline_projector->handle_event(event);
	m_last_event_record_id = record.value("record_id", std::string{});
	const bool changed = m_stream_state->apply_event(record);
	const std::string type = record.value("type", std::string{});
	if(type == "alert_detected" || type == "alert_recovered") {
		json alert = record.value("source", json::object());
		const json detail = record.value("detail", json::object());
		if(detail.is_object()) {
			for(const auto &[key, value] : detail.items()) alert[key] = value;
		}
		const std::string key = alert.value("state_key", alert.value("alert_id", std::string{}));
		if(!key.empty()) {
			if(type == "alert_detected") m_active_alerts[key] = std::move(alert);
			else m_active_alerts.erase(key);
		}
	}
	if(changed) write_topology_event(record);
	write_topology(event.time_epoch, record);
	return rc;
}

int stm_projector::project_metrics(const json &record) {
	if(!record.is_object() || record.value("record_type", std::string{}) != "metrics_snapshot") {
		return 0;
	}
	const double time = record.value("time", 0.0);
	if(time <= 0.0 || !record.contains("metrics") || !record["metrics"].is_array() ||
	   !record.contains("interfaces") || !record["interfaces"].is_array()) {
		return 0;
	}
	m_current_metrics = record["metrics"].get<json::array_t>();
	m_current_interfaces = record["interfaces"].get<json::array_t>();
	m_last_metrics_record_id = record.value("record_id", std::string{});
	if(m_timeline_availability_writer) {
		m_timeline_availability_writer->dump_at(time, json{
			{"schema_version", 1},
			{"record_type", "timeline_availability"},
			{"record_id", m_last_metrics_record_id + ":timeline-availability"},
			{"source_record_id", m_last_metrics_record_id},
			{"capture_id", record.value("capture_id", std::string{})},
			{"time", time},
		});
	}
	m_metrics_projector->append_snapshot(time, m_current_metrics, m_current_interfaces, record);
	write_topology(time, record);
	return 0;
}

void stm_projector::write_topology(double time, const json &source_record) {
	if(!m_topology_writer || !m_topology_projector || !m_stream_state) return;
	json::array_t alerts;
	for(const auto &[_, alert] : m_active_alerts.items()) alerts.push_back(alert);
	const auto streams = m_stream_state->snapshot(time).value("streams", json::array_t{});
	const auto topology = m_topology_projector->build(time, streams, m_current_interfaces, m_current_metrics, alerts);
	m_topology_writer->dump(topology);
	if(m_topology_state) {
		json source{
			{"record_id", source_record.value("record_id", std::string{})},
			{"event_record_id", m_last_event_record_id},
			{"metrics_record_id", m_last_metrics_record_id},
		};
		m_topology_state->publish(time, topology, source);
	}
}

void stm_projector::write_topology_event(const json &event) {
	if(!m_topology_events_writer) return;
	const std::string type = event.value("type", std::string{});
	if(type != "flow_detected" && type != "flow_lost" && type != "flow_recovered") return;
