				out.advanced = true;
				continue;
			}
			if(handler(record) != 0) {
				return out;
			}
			cursor = journal_reader::cursor{
				.path = relative,
				.offset = next_offset,
				.record_id = record.value("record_id", std::string{}),
			};
			++out.records;
			out.advanced = true;
