bool as_event_record(const json &input, event_record &out) {
	if(!input.is_object() || input.value("record_type", std::string{}) != "event") {
		return false;
	}
	const double time = input.value("event_time", input.value("time", 0.0));
	const std::string type = input.value("type", std::string{});
	if(time <= 0.0 || type.empty()) {
		return false;
	}
	out = event_record{
		.time_epoch = time,
		.type = type,
		.source = input.value("source", json::object()),
		.detail = input.value("detail", json::object()),
	};
	return true;
}

enum class journal_kind {
	event,
	metrics,
};

struct pending_journal_record {
	double time{0.0};
	journal_kind kind{journal_kind::event};
	std::size_t ordinal{0};
	json record;
};

double record_time(const json &record, journal_kind kind) {
	if(kind == journal_kind::event) {
		return record.value("event_time", record.value("time", 0.0));
	}
	return record.value("time", 0.0);
}
