#include "journal_reader.h"
#include "trace.h"

#include <algorithm>
#include <fstream>
#include <system_error>
#include <utility>

namespace {
struct journal_file_start {
	std::string record_id;
	std::string capture_id;
};

journal_file_start first_record(const std::filesystem::path &path) {
	std::ifstream input(path);
	std::string line;
	while(std::getline(input, line)) {
		if(line.empty()) continue;
		try {
			const json record = json::parse(line);
			if(record.is_object()) {
				return journal_file_start{
					.record_id = record.value("record_id", std::string{}),
					.capture_id = record.value("capture_id", std::string{}),
				};
			}
		}
		catch(const json::parse_error &) {
			break;
		}
	}
	return {};
}

bool record_matches_capture(const std::string &record_id, const std::string &capture_id) {
	return !capture_id.empty() && record_id.size() > capture_id.size() &&
	       record_id.compare(0, capture_id.size(), capture_id) == 0 &&
	       record_id[capture_id.size()] == ':';
}

void reset_replaced_cursor(journal_reader::cursor &cursor,
	                        const std::string &path,
	                        std::uint64_t file_size,
	                        const char *reason) {
	trace(1, "journal reader: cursor reset path=%s reason=%s old_offset=%llu file_size=%llu",
	      path.c_str(), reason,
	      static_cast<unsigned long long>(cursor.offset),
	      static_cast<unsigned long long>(file_size));
	cursor.offset = 0;
	cursor.record_id.clear();
	cursor.file_start_record_id.clear();
}

void advance_cursor(journal_reader::cursor &cursor,
	                const std::string &path,
	                std::uint64_t offset,
	                const std::string &record_id) {
	const bool path_changed = cursor.path != path;
	if(path_changed) {
		cursor.path = path;
		cursor.file_start_record_id.clear();
	}
	cursor.offset = offset;
	cursor.record_id = record_id;
