}
function TimelineGapBands({ gaps, range, label = false }: { gaps: TimelineDataGap[]; range: { start: number; end: number }; label?: boolean }) {
  return <>{gaps.map((gap) => {
    const from = Math.max(range.start, gap.from);
    const to = Math.min(range.end, gap.to);
    if (to <= from) return null;
    const start = percent(from, range.start, range.end);
    const end = percent(to, range.start, range.end);
    return <div key={`${gap.reason}:${from}:${to}`} className="timeline-gap-band" style={{ left: `${start}%`, width: `${Math.max(0.4, end - start)}%` }} title="Monitoring data unavailable" aria-label={label ? "Monitoring data unavailable" : undefined} />;
  })}</>;
}

function splitTimelineSegments(
  segments: Array<{ start: number; end: number | null }>,
  gaps: TimelineDataGap[],
  range: { start: number; end: number }
) {
  return segments.flatMap((segment) => {
    const end = segment.end ?? range.end;
    let pieces = [{ start: Math.max(range.start, segment.start), end: Math.min(range.end, end) }];
    for (const gap of gaps) {
      pieces = pieces.flatMap((piece) => {
        if (gap.to <= piece.start || gap.from >= piece.end) return [piece];
        const next: Array<{ start: number; end: number }> = [];
        if (piece.start < gap.from) next.push({ start: piece.start, end: Math.min(piece.end, gap.from) });
        if (piece.end > gap.to) next.push({ start: Math.max(piece.start, gap.to), end: piece.end });
        return next;
      });
    }
    return pieces.filter((piece) => piece.end > piece.start).map((piece) => ({
      start: piece.start,
      end: segment.end === null && piece.end >= range.end ? null : piece.end
    }));
  });
}

