  private ensureTimelineRow(input: NormalizedTimelineInput): TimelineRow {
    const timelineKey = input.subjectType === "flow" ? `${input.streamKey}::${input.flowKey ?? ""}` : input.streamKey;
    const existing = this.timeline.get(timelineKey);
    if (existing) {
      existing.interfaceId = input.interfaceId ?? existing.interfaceId;
      if (existing.interfaceId !== undefined) {
        existing.interfaceName = this.interfaceById(existing.interfaceId)?.name ?? existing.interfaceName;
      }
      existing.kind = input.proto;
      existing.proto = input.proto;
      existing.label = input.label || existing.label;
      existing.role = input.role ?? existing.role;
      existing.endpointSrc = input.endpointSrc ?? existing.endpointSrc;
      existing.endpointDst = input.endpointDst ?? existing.endpointDst;
      existing.scope = input.scope.known ? input.scope : existing.scope;
      return existing;
    }

    const interfaceName = input.interfaceId !== undefined ? this.interfaceById(input.interfaceId)?.name : undefined;
    const row: TimelineRow = {
      rowType: input.subjectType === "flow" ? "flow" : "stream",
      streamKey: input.streamKey,
      flowKey: input.flowKey,
      parentStreamKey: input.subjectType === "flow" ? input.streamKey : undefined,
      kind: input.proto,
      proto: input.proto,
      label: input.label,
      role: input.role,
      endpointSrc: input.endpointSrc,
      endpointDst: input.endpointDst,
      interfaceId: input.interfaceId,
      interfaceName,
      scope: input.scope,
      active: input.kind !== "stream_lost",
      firstSeen: input.time,
      lastSeen: input.time,
      segments: []
    };
    this.timeline.set(timelineKey, row);
    return row;
  }
}

