  diagnosticLog: toBool(argv.diagnosticLog ?? process.env.STM_DIAGNOSTIC_LOG, false),
  clientDist: path.resolve(rootDir, "client/dist"),
  dashboardLayoutsFile: path.resolve(rootDir, "dashboard-layouts.json"),
  maintenanceSettingsFile: path.resolve(rootDir, "maintenance-settings.json"),
  runtimeSettingsFile: path.resolve(rootDir, "runtime-settings.json")
