  return { time, streams: items, interfaces: [] };
}

export function enrichProjectedStreamSnapshot(
  snapshot: StreamsSnapshot,
  interfaces: NormalizedInterfaceInput[],
  metrics: NormalizedMetricInput[]
): StreamsSnapshot {
  const interfaceItems: InterfaceListItem[] = interfaces.map(({ hasMetrics: _hasMetrics, ...item }) => ({ ...item, streamCount: 0 }));
  const interfaceNames = new Map(interfaceItems.filter((item) => item.interfaceId !== undefined).map((item) => [item.interfaceId!, item.name]));
  const metricsByFlow = new Map(metrics.map((metric) => [metric.flowKey, metric]));
  const streams = snapshot.streams.map((stream) => {
    const flows = stream.flows.map((flow) => {
      const metric = metricsByFlow.get(flow.flowKey);
      const interfaceName = flow.interfaceName ?? (flow.interfaceId !== undefined ? interfaceNames.get(flow.interfaceId) : undefined);
      return { ...flow, interfaceName, bitrate: metric?.metrics.bitrate ?? flow.bitrate };
    });
    const interfaceName = stream.interfaceName ?? (stream.interfaceId !== undefined ? interfaceNames.get(stream.interfaceId) : undefined);
    return { ...stream, interfaceName, flows, flowCount: flows.length, bitrate: sumBitrate(flows.map((flow) => flow.bitrate)) };
  });
  const streamCounts = new Map<number, number>();
  for (const stream of streams) {
    if (stream.interfaceId !== undefined) {
      streamCounts.set(stream.interfaceId, (streamCounts.get(stream.interfaceId) ?? 0) + 1);
    }
  }
  return {
    ...snapshot,
    interfaces: interfaceItems.map((item) => ({ ...item, streamCount: item.interfaceId !== undefined ? streamCounts.get(item.interfaceId) ?? 0 : 0 })),
    streams
  };
}

function sumBitrate(stats: NumericStat[]): NumericStat {
  const total = (field: keyof NumericStat) => stats
    .map((stat) => stat[field])
    .filter((value): value is number => typeof value === "number" && Number.isFinite(value))
    .reduce((sum, value) => sum + value, 0);
  return { value: total("value"), avg: total("avg"), min: total("min"), max: total("max"), count: total("count") };
}

export function activeProjectedStreams(streams: JsonRecord) {
  return Object.entries(streams)
    .filter(([, stream]) => isRecord(stream) && stream.active === true)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([, source]) => {
      const stream: JsonRecord = {};
      for (const field of ["stream_key", "interface_id", "scope", "vlan", "endpoint", "first_seen", "last_seen"]) {
        if (source[field] !== undefined) stream[field] = source[field];
      }
      stream.flows = Object.entries(isRecord(source.flows) ? source.flows : {})
        .filter(([, flow]) => isRecord(flow) && flow.active === true)
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([, sourceFlow]) => {
          const activeFlow = isRecord(sourceFlow) ? sourceFlow : {};
          const flow: JsonRecord = {};
          for (const field of ["flow_key", "interface_id", "scope", "vlan", "endpoint", "role", "first_seen", "last_seen"]) {
            if (activeFlow[field] !== undefined) flow[field] = activeFlow[field];
          }
          return flow;
        });
      return { proto: stringValue(source.proto), stream };
    });
}

async function findLatestCheckpoint(root: string, time: number): Promise<JsonRecord | undefined> {
  let latest: JsonRecord | undefined;
  let latestTime = Number.NEGATIVE_INFINITY;
  for (const file of listFiles(root, (name) => name.endsWith(".json"))) {
    try {
      const entry = JSON.parse(await import("node:fs/promises").then(({ readFile }) => readFile(file, "utf8"))) as JsonRecord;
      const entryTime = Number(entry.time ?? 0);
      if (Number.isFinite(entryTime) && entryTime <= time && entryTime >= latestTime) {
        latest = entry;
        latestTime = entryTime;
      }
    } catch {
      // A partially written checkpoint is ignored.
    }
  }
  return latest;
}

function copyIdentity(target: JsonRecord, source: JsonRecord) {
  for (const field of ["proto", "interface_id", "scope", "vlan"]) {
    if (source[field] !== undefined) target[field] = source[field];
  }
}

function listNdjsonFiles(root: string, from = Number.NEGATIVE_INFINITY, to = Number.POSITIVE_INFINITY) {
  return listFiles(root, (name) => name.endsWith(".ndjson"))
    .filter((file) => fileMayContainTime(file, from, to));
}

function fileMayContainTime(file: string, from: number, to: number) {
  const date = path.basename(path.dirname(file));
  const fileName = path.basename(file);
  if (date.length !== 8 || Number.isNaN(Number(date)) || !/^[0-9]{2}/.test(fileName)) return true;
  const hour = Number(fileName.slice(0, 2));
  const start = Date.UTC(Number(date.slice(0, 4)), Number(date.slice(4, 6)) - 1, Number(date.slice(6, 8)), hour) / 1000;
  return Number.isFinite(start) && start <= to && start + 3600 >= from;
}
function listFiles(root: string, include: (name: string) => boolean): string[] {
  if (!existsSync(root)) return [];
  const files: string[] = [];
  const visit = (dir: string) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) visit(full);
      else if (entry.isFile() && include(entry.name)) files.push(full);
    }
  };
  visit(root);
  return files.sort();
}
function parseRecord(line: string): JsonRecord | undefined {
  try { const value = JSON.parse(line) as unknown; return isRecord(value) ? value : undefined; } catch { return undefined; }
}
function isRecord(value: unknown): value is JsonRecord { return Boolean(value) && typeof value === "object" && !Array.isArray(value); }
function stringValue(value: unknown) { return typeof value === "string" ? value : ""; }
function isLifecycle(type: string, subject: string) { return type === `${subject}_detected` || type === `${subject}_recovered` || type === `${subject}_lost`; }
function isDetect(type: string) { return type.endsWith("_detected") || type.endsWith("_recovered"); }

