type RunningTail = { start(): void; stop(): void };

async function main() {
  ensureLogFilesExist();
  diagnostic(`startup source=projected cwd=${process.cwd()} root=${config.rootDir} logDir=${config.logDir} port=${config.port}`);
  diagnosticInputs();

  const app = fastify({ logger: config.httpAccessLog });
  const alertsSettings = config.stmConfigFile ? new AlertsSettings(config.stmConfigFile) : undefined;
  const protocolMapSettings = config.stmConfigFile ? new ProtocolMapSettings(config.stmConfigFile) : undefined;
  const maintenanceSettings = await MaintenanceSettings.load({
    definitionFile: config.maintenanceSettingsFile,
    runtimeFile: config.runtimeSettingsFile,
    defaults: { lostRetentionSec: config.lostRetentionSec, historyWindowSec: config.historyWindowSec, staleAfterSec: config.staleAfterSec, diagnosticLog: config.diagnosticLog }
  });
  Object.assign(config, maintenanceSettings.get().values);
  const store = new StreamStore(config.historyWindowSec, config.timelineWindowSec, config.staleAfterSec, config.lostRetentionSec, config.maxEvents, config.maxTimelineRows);
  const now = Date.now() / 1000;
  const initialEvents = await queryEventsHistory({ from: now - 24 * 3600, to: now, limit: config.maxEvents });
  for (const event of initialEvents.reverse()) store.addEvent(event);

  const initialTopology = await queryProjectedTopologyAt({ checkpointDir: config.topologyCheckpointDir, updatesDir: config.topologyUpdatesDir, time: now });
  if (initialTopology) store.applyTopologySnapshot(initialTopology);
  diagnostic(`initial state events=${store.listEvents({ limit: config.maxEvents }).length} topology=${initialTopology ? "loaded" : "missing"}`);

  const sockets = new SocketServer(app.server, store, config.streamsPatchIntervalMs, config.wsMaxBufferedBytes);
  await registerRoutes(app, store, maintenanceSettings, alertsSettings, protocolMapSettings, (values) => {
    Object.assign(config, values);
    store.updateRuntimeConfig(values);
    sockets.broadcastConfig(values);
  });
  if (existsSync(config.clientDist)) {
    await app.register(fastifyStatic, { root: config.clientDist, prefix: "/" });
    app.setNotFoundHandler((request, reply) => {
      if (request.raw.url?.startsWith("/api") || request.raw.url === "/ws") return reply.code(404).send({ error: "not found" });
      return reply.sendFile("index.html");
    });
  }

  sockets.start();
  const { tails, flushMetrics } = await createProjectedTails(app, store, sockets);
  tails.forEach((tail) => tail.start());
  const close = async () => { flushMetrics(); tails.forEach((tail) => tail.stop()); await app.close(); };
  process.on("SIGINT", () => void close());
  process.on("SIGTERM", () => void close());
  await app.listen({ host: config.host, port: config.port });
}

async function createProjectedTails(app: FastifyInstance, store: StreamStore, sockets: SocketServer): Promise<{ tails: RunningTail[]; flushMetrics: () => void }> {
  const state = await loadProjectedStreamState(config.streamStateDir, Number.POSITIVE_INFINITY);
  const applyStreams = (time: number) => store.applyStreamSnapshot(materializeProjectedStreamStates(state.streams, time), time);
  if (state.hasRecords) applyStreams(Date.now() / 1000);

  const streams = new RotatingNdjsonTail({ root: `${config.streamStateDir}/delta`, extension: ".ndjson", pollMs: config.pollMs, startAtLatestFile: true,
    recordId: sourceRecordId,
    initialSkipRecordIds: state.latestDeltaRecordIds,
    onLine: (line) => { try { const delta = parseRecord(line); const time = Number(delta?.time ?? 0); if (!delta || !Number.isFinite(time) || time < state.checkpointTime) return; applyProjectedLifecycleEvent(state.streams, delta.event); applyStreams(time); } catch (error) { app.log.warn({ error }, "failed to parse projected stream delta"); } },
    onError: (error) => app.log.warn({ error }, "failed to tail projected stream deltas") });
  const metricBatch = createMetricSampleBatcher(store, app);
  const metrics = new RotatingNdjsonTail({ root: config.metricsSamples1sDir, extension: ".ndjson", pollMs: config.pollMs, startAtLatestFile: true,
    onLine: metricBatch.push, onError: (error) => app.log.warn({ error }, "failed to tail projected metrics") });
  const events = new RotatingNdjsonTail({ root: config.eventJournalDir, extension: ".ndjson", pollMs: config.pollMs, startAtLatestFile: true,
    onLine: (line) => ingestEvent(store, line, app), onError: (error) => app.log.warn({ error }, "failed to tail event journal") });
  const availability = new RotatingNdjsonTail({ root: config.timelineAvailabilityDir, extension: ".ndjson", pollMs: config.pollMs, startAtEnd: true,
    onLine: (line) => { if (parseRecord(line)?.record_type === "timeline_availability") sockets.broadcastLiveHeartbeat(); },
    onError: (error) => app.log.warn({ error }, "failed to tail timeline availability") });

  const timeline = new TailFile({ path: config.timelineLiveFile, pollMs: config.pollMs,
    onLine: (line) => ingestTimeline(store, line, app), onError: (error) => app.log.warn({ error }, "failed to tail projected timeline live") });
  const topology = new TailFile({ path: config.topologyLiveFile, pollMs: config.pollMs,
    onLine: (line) => ingestTopology(store, line, app), onError: (error) => app.log.warn({ error }, "failed to tail projected topology live") });
  return { tails: [streams, metrics, events, availability, timeline, topology], flushMetrics: metricBatch.flush };
}

function createMetricSampleBatcher(store: StreamStore, app: FastifyInstance) {
  const interfaces: NormalizedInterfaceInput[] = [];
  const metrics: NormalizedMetricInput[] = [];
  let timer: NodeJS.Timeout | undefined;

  const flush = () => {
    if (timer) clearTimeout(timer);
    timer = undefined;
    const interfaceBatch = interfaces.splice(0, interfaces.length);
    const metricBatch = metrics.splice(0, metrics.length);
    if (interfaceBatch.length > 0) store.upsertInterfaces(interfaceBatch);
    if (metricBatch.length > 0) store.addMetrics(metricBatch);
  };

  return {
    push: (line: string) => {
      try {
        const sample = normalizeMetricSampleLine(line);
        if (!sample) return;
        if (sample.interface) interfaces.push(sample.interface);
        if (sample.metric) metrics.push(sample.metric);
        if (!timer) timer = setTimeout(flush, 50);
      } catch (error) {
        app.log.warn({ error }, "failed to parse metric sample");
      }
    },
    flush
