import { promises as fs } from "node:fs";

const READ_CHUNK_BYTES = 1024 * 1024;

export type TailFileOptions = {
  path: string;
  pollMs: number;
  onLine: (line: string) => void;
  onChunk?: (info: {
    start: number;
    end: number;
    bytes: number;
    lines: number;
    observedAt: number;
    processedAt: number;
    processingMs: number;
  }) => void;
  onError?: (error: unknown) => void;
};

export class TailFile {
  private offset = 0;
  private inode?: number;
  private dev?: number;
  private buffer = "";
  private timer?: NodeJS.Timeout;
  private reading = false;

  constructor(private readonly options: TailFileOptions) {}

  start() {
    this.timer = setInterval(() => void this.tick(), this.options.pollMs);
    void this.tick();
  }

  stop() {
    if (this.timer) clearInterval(this.timer);
  }

  private async tick() {
    if (this.reading) return;
    this.reading = true;
    try {
      const stat = await fs.stat(this.options.path);
      const rotated = this.inode !== undefined && (stat.ino !== this.inode || stat.dev !== this.dev);
      const truncated = stat.size < this.offset;

      if (rotated || truncated) {
        this.offset = 0;
        this.buffer = "";
      }

      this.inode = stat.ino;
      this.dev = stat.dev;

      if (stat.size > this.offset) {
        const start = this.offset;
        const end = stat.size;
        const observedAt = Date.now();
        const lines = await this.readRange(start, end);
        const processedAt = Date.now();
        this.offset = end;
        this.options.onChunk?.({
          start,
          end,
          bytes: end - start,
          lines,
          observedAt,
          processedAt,
          processingMs: processedAt - observedAt
        });
      }
    } catch (error: any) {
      if (error?.code !== "ENOENT") this.options.onError?.(error);
    } finally {
      this.reading = false;
    }
  }

  private async readRange(start: number, end: number) {
    const handle = await fs.open(this.options.path, "r");
    try {
      let position = start;
      let lineCount = 0;
      while (position < end) {
        const length = Math.min(READ_CHUNK_BYTES, end - position);
        const buffer = Buffer.alloc(length);
        const { bytesRead } = await handle.read(buffer, 0, length, position);
        if (bytesRead <= 0) break;
        lineCount += this.consume(buffer.subarray(0, bytesRead).toString("utf8"));
        position += bytesRead;
      }
      return lineCount;
    } finally {
      await handle.close();
    }
  }

  private consume(chunk: string) {
    let lineCount = 0;
    this.buffer += chunk;
    const lines = this.buffer.split(/\r?\n/);
    this.buffer = lines.pop() ?? "";
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed) {
        lineCount += 1;
        this.options.onLine(trimmed);
      }
    }
    return lineCount;
  }
}
