/** Tails lexically ordered hourly and part-suffixed JSONL files without consuming a partial final line. */
export class RotatingNdjsonTail {
  private cursorPath?: string;
  private cursorOffset = 0;
  private timer?: NodeJS.Timeout;
  private reading = false;
  private readonly recentRecordIds = new Set<string>();
  private readonly recentRecordOrder: string[] = [];
  private readonly initialSkipRecordIds?: ReadonlySet<string>;

  constructor(private readonly options: RotatingNdjsonTailOptions) {
    this.initialSkipRecordIds = options.initialSkipRecordIds;
  }

  start() {
    this.timer = setInterval(() => void this.tick(), this.options.pollMs);
    void this.tick();
  }

  stop() {
    if (this.timer) clearInterval(this.timer);
  }

  private async tick() {
    if (this.reading) return;
    this.reading = true;
    try {
      const files = await this.listFiles();
      if (files.length === 0) return;

      if (!this.cursorPath && this.options.startAtEnd) {
        const latestFile = files[files.length - 1];
        this.cursorPath = latestFile;
        this.cursorOffset = (await fs.stat(latestFile)).size;
        return;
      }

      let index = this.cursorPath ? files.indexOf(this.cursorPath) : (this.options.startAtLatestFile ? files.length - 1 : 0);
      if (index < 0) index = files.findIndex((file) => !this.cursorPath || file > this.cursorPath);
      if (index < 0) return;

      for (; index < files.length; index += 1) {
        const file = files[index];
        if (file !== this.cursorPath) {
          this.cursorPath = file;
          this.cursorOffset = 0;
        }
        const hasPartialLine = await this.readAvailable(file);
        if (hasPartialLine || index === files.length - 1) break;
      }
    } catch (error) {
      this.options.onError?.(error);
    } finally {
      this.reading = false;
    }
  }

  private async listFiles() {
    const files: string[] = [];
    const walk = async (directory: string): Promise<void> => {
      let entries;
      try {
        entries = await fs.readdir(directory, { withFileTypes: true });
      } catch (error: any) {
        if (error?.code === "ENOENT") return;
        throw error;
      }
      for (const entry of entries) {
        const candidate = path.join(directory, entry.name);
        if (entry.isDirectory()) await walk(candidate);
        else if (entry.isFile() && entry.name.endsWith(this.options.extension)) files.push(candidate);
      }
    };
    await walk(this.options.root);
    return files.sort();
  }

  private async readAvailable(file: string) {
