/** Three missing per-second snapshots indicate an unavailable monitoring interval. */
export const AVAILABILITY_MAX_INTERVAL_SEC = 3;

export async function queryTimelineDataGaps(options: QueryOptions): Promise<TimelineDataGap[]> {
  if (!existsSync(config.timelineAvailabilityDir)) return [];

  const prior = await readLatestAvailabilityAtOrBefore(options.from);
  const points = [
